// Bai tap ngu phap hsk4v3 — soan rieng theo trinh do (sinh tu data-grammar/hsk4v3/).
window.GRAMMAR_EXTRA = Object.assign(window.GRAMMAR_EXTRA || {}, {"/lessons/hsk4v3-bai-1.html":[{"point":"指示代词“任何” — bất kỳ, bất cứ","items":[{"context":"“Sau này có bất kỳ vấn đề gì đều có thể đến tìm cô.”","pre":"你们以后有","blank":"任何","post":"问题都可以来找我。","options":["任何","每","所有的"],"answer":0,"explanation":"任何 + danh từ + 都 + V."},{"context":"“Bất kỳ ai cũng không được đến muộn.”","pre":"明天8点出发，任何人","blank":"也","post":"不能迟到。","options":["也","就","才"],"answer":0,"explanation":"任何……也 + phủ định."},{"context":"“Có bất kỳ thông báo nào, tôi đều báo cho bạn ngay.”","pre":"学校有任何通知，我","blank":"都","post":"会第一时间告诉你。","options":["都","还","再"],"answer":0,"explanation":"任何……都…… — 都 đứng trước động từ của vế sau."},{"context":"“Việc này anh ấy không nói với bất kỳ ai.”","pre":"这件事他没有告诉","blank":"任何","post":"人。","options":["任何","什么的","哪"],"answer":0,"explanation":"没有 + V + 任何 + N."},{"context":"“Bất cứ lúc nào em cũng có thể gọi cho cô.”","pre":"","blank":"任何","post":"时候你都可以给我打电话。","options":["任何","那","一"],"answer":0,"explanation":"任何时候 = bất cứ lúc nào."},{"type":"sort","context":"Sắp xếp: “Em có bất kỳ vấn đề gì đều có thể hỏi tôi.”","words":["你","有","任何","问题","都","可以","问我"],"answer":"你有任何问题都可以问我。","explanation":"任何 + N + 都 + 可以 + V."},{"type":"sort","context":"Sắp xếp: “Bất kỳ ai cũng không được đến muộn.”","words":["任何人","也","不能","迟到"],"answer":"任何人也不能迟到。","explanation":"任何人 + 也 + 不能."},{"type":"sort","context":"Sắp xếp: “Việc này anh ấy không nói với ai cả.”","words":["他","没有","告诉","任何人","这件事"],"answer":"这件事他没有告诉任何人。","explanation":"Phủ định: 没有 + V + 任何 + N."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"任何的学生都可以参加。","isCorrect":false,"correctVersion":"任何学生都可以参加。","explanation":"任何 + N, không thêm 的."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"我们有任何问题都可以找王老师。","isCorrect":true,"correctVersion":"","explanation":"Đúng: 任何问题 + 都 + 可以."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"他不认识任何人们。","isCorrect":false,"correctVersion":"他不认识任何人。","explanation":"任何 không đi với 们."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Bất cứ lúc nào em cũng có thể gọi điện cho cô.","answer":"任何时候你都可以给我打电话。","answerPy":"Rènhé shíhou nǐ dōu kěyǐ gěi wǒ dǎdiànhuà.","explanation":"任何时候 + 都 + 可以."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Trong thư viện, bất kỳ ai cũng không được nói to.","answer":"在图书馆里，任何人都不能大声说话。","answerPy":"Zài túshūguǎn lǐ, rènhé rén dōu bù néng dà shēng shuōhuà.","explanation":"任何人 + 都 / 也 + 不能."}]},{"point":"假设复句“要是……，就……” — nếu … thì …","items":[{"context":"“Nếu xin được học bổng thì …”","pre":"","blank":"要是","post":"申请到奖学金，就能减轻不少经济压力。","options":["要是","虽然","因为"],"answer":0,"explanation":"要是 nêu giả thiết."},{"context":"“… thì đi leo núi với tớ nhé.”","pre":"你要是明天有时间，","blank":"就","post":"跟我一起去爬山吧。","options":["就","才","也"],"answer":0,"explanation":"要是……，就……"},{"context":"“… thì chúng ta hỏi người khác.”","pre":"要是她不愿意参加比赛，我们","blank":"就","post":"再问问别人。","options":["就","还","都"],"answer":0,"explanation":"就 đứng sau chủ ngữ 我们."},{"context":"“Nếu bạn đói thì mình đi nhà ăn trước.” (ôn từ mới)","pre":"要是你饿了，我们就先去","blank":"食堂","post":"吧。","options":["食堂","签证","证件"],"answer":0,"explanation":"食堂 = nhà ăn."},{"context":"“Nếu không làm visa thì không thể sang Trung Quốc du học.”","pre":"","blank":"要是","post":"不办签证，就不能来中国留学。","options":["要是","一方面","随着"],"answer":0,"explanation":"要是 + phủ định 不……，就不能……"},{"type":"sort","context":"Sắp xếp: “Nếu mai mưa thì chúng ta không đi nữa.”","words":["要是","明天","下雨","，","我们","就","不去了"],"answer":"要是明天下雨，我们就不去了。","explanation":"要是 + giả thiết，chủ ngữ + 就 + V."},{"type":"sort","context":"Sắp xếp: “Nếu bạn mệt rồi thì nghỉ một chút đi.”","words":["你","要是","累了","，","就","休息","一下吧"],"answer":"你要是累了，就休息一下吧。","explanation":"要是 đứng sau chủ ngữ 你."},{"type":"sort","context":"Sắp xếp: “Nếu có vấn đề thì đến tìm tôi.”","words":["要是","有","问题","，","就","来","找我"],"answer":"要是有问题，就来找我。","explanation":"要是……，就……"},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"要是你不舒服，就去看医生吧。","isCorrect":true,"correctVersion":"","explanation":"Đúng: 要是……，就……"},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"要是明天有时间，我们去就看电影。","isCorrect":false,"correctVersion":"要是明天有时间，我们就去看电影。","explanation":"就 đứng trước động từ 去."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"要是我有钱，我就买一辆新车。","isCorrect":true,"correctVersion":"","explanation":"Đúng: chủ ngữ 我 + 就 + V."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Nếu xin được học bổng thì tôi sẽ học thạc sĩ ở Trung Quốc.","answer":"要是申请到奖学金，我就在中国读硕士。","answerPy":"Yàoshi shēnqǐng dào jiǎngxuéjīn, wǒ jiù zài Zhōngguó dú shuòshì.","explanation":"要是……，就…… + từ mới 申请, 奖学金, 硕士."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Nếu bạn không hiểu thì hỏi cô giáo đi.","answer":"要是你不懂，就问老师吧。","answerPy":"Yàoshi nǐ bù dǒng, jiù wèn lǎoshī ba.","explanation":"要是……，就……吧."}]},{"point":"介词“随着” — cùng với, theo (sự thay đổi)","items":[{"context":"“Cùng với sự phát triển của Trung Quốc …”","pre":"","blank":"随着","post":"中国的发展，越来越多的外国学生来中国学习。","options":["随着","通过","除了"],"answer":0,"explanation":"随着 + N 的发展."},{"context":"“Cùng với trình độ tiếng Trung nâng cao …”","pre":"随着中文水平的","blank":"提高","post":"，我现在能看懂中文报纸了。","options":["提高","知识","方面"],"answer":0,"explanation":"随着……的提高."},{"context":"“Theo trời ngày càng nóng …”","pre":"随着天气","blank":"越来越","post":"热，人们都换上了凉快的衣服。","options":["越来越","一方面","任何"],"answer":0,"explanation":"随着 + 越来越 + tính từ."},{"context":"“Thông qua những giao lưu này …” (phân biệt với 随着)","pre":"","blank":"通过","post":"这些交流，外国学生能更快地适应中国的大学生活。","options":["通过","随着","要是"],"answer":0,"explanation":"通过 = nhờ/qua cách gì; 随着 = theo sự thay đổi."},{"context":"“… giao lưu cũng ngày càng nhiều.”","pre":"随着来中国留学的人越来越多，中国学生和外国学生的交流","blank":"也","post":"越来越多。","options":["也","就","才"],"answer":0,"explanation":"Vế sau thường có 也 + 越来越."},{"type":"sort","context":"Sắp xếp: “Cùng với kinh tế phát triển, đời sống mọi người ngày càng tốt.”","words":["随着","经济","的","发展","，","人们的生活","越来越好"],"answer":"随着经济的发展，人们的生活越来越好。","explanation":"随着 + N 的 + 发展，……越来越……"},{"type":"sort","context":"Sắp xếp: “Cùng với tuổi tác tăng lên, cậu ấy ngày càng hiểu chuyện.”","words":["随着","年龄","的","增长","，","他","越来越","懂事了"],"answer":"随着年龄的增长，他越来越懂事了。","explanation":"随着……的增长."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"随着我到了北京，就给你打电话。","isCorrect":false,"correctVersion":"我到了北京以后，就给你打电话。","explanation":"“Đến Bắc Kinh” là hành động, không phải sự thay đổi dần → dùng ……以后."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"随着生活水平的提高，人们越来越关注身体健康。","isCorrect":true,"correctVersion":"","explanation":"Đúng: 随着……的提高，……越来越……"},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"人们都换上了凉快的衣服，随着天气越来越热。","isCorrect":false,"correctVersion":"随着天气越来越热，人们都换上了凉快的衣服。","explanation":"Cụm 随着 đặt ở đầu câu."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Cùng với sự phát triển kinh tế, ngày càng nhiều người đi du lịch nước ngoài.","answer":"随着经济的发展，越来越多的人去国外旅游。","answerPy":"Suízhe jīngjì de fāzhǎn, yuèláiyuè duō de rén qù guó wài lǚyóu.","explanation":"随着……的发展，越来越多的……"}]},{"point":"并列复句“一方面……，另一方面……” — một mặt …, mặt khác …","items":[{"context":"“… mặt khác vì tiện.”","pre":"他经常在网上买东西，一方面因为便宜，","blank":"另一方面","post":"因为方便。","options":["另一方面","一方面","另外"],"answer":0,"explanation":"一方面……，另一方面……"},{"context":"“… mặt khác cũng giảm được áp lực.”","pre":"多做运动一方面能让身体更健康，另一方面","blank":"也","post":"能减轻压力。","options":["也","就","才"],"answer":0,"explanation":"Vế 另一方面 thường có 也."},{"context":"“Một mặt là để học ngôn ngữ …”","pre":"来中国留学，","blank":"一方面","post":"是为了学习语言，另一方面也是为将来做准备。","options":["一方面","随着","要是"],"answer":0,"explanation":"Vế đầu dùng 一方面."},{"context":"“… kiến thức về thương mại quốc tế.” (ôn từ 方面)","pre":"我想了解更多国际贸易","blank":"方面","post":"的知识。","options":["方面","知识","专业"],"answer":0,"explanation":"N + 方面的知识."},{"type":"sort","context":"Sắp xếp: “Tôi đạp xe đi làm, một mặt tốt cho môi trường, mặt khác cũng tốt cho sức khỏe.”","words":["我","骑车上班","，","一方面","对环境好","，","另一方面","对身体也好"],"answer":"我骑车上班，一方面对环境好，另一方面对身体也好。","explanation":"一方面……，另一方面……也……"},{"type":"sort","context":"Sắp xếp: “Học tiếng Trung một mặt vì công việc, mặt khác để hiểu văn hóa Trung Quốc.”","words":["学中文","一方面","为了","工作","，","另一方面","为了","了解中国文化"],"answer":"学中文一方面为了工作，另一方面为了了解中国文化。","explanation":"Hai vế cân đối: 为了……，为了……"},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"他一方面是学生，另外方面是老师。","isCorrect":false,"correctVersion":"他一方面是学生，另一方面也是老师。","explanation":"Phải là 另一方面."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"我住在学校里，一方面因为便宜，另一方面因为方便。","isCorrect":true,"correctVersion":"","explanation":"Đúng: nêu hai lý do song song."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"一方面天气很好，一方面我们去公园吧。","isCorrect":false,"correctVersion":"天气很好，我们去公园吧。","explanation":"Hai vế không phải hai mặt song song của một sự việc → không dùng cấu trúc này."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Tôi chọn ngành kinh tế, một mặt vì có hứng thú, mặt khác vì sau này muốn làm thương mại quốc tế.","answer":"我选择经济专业，一方面是因为感兴趣，另一方面是因为将来想做国际贸易。","answerPy":"Wǒ xuǎnzé jīngjì zhuānyè, yìfāngmiàn shì yīnwèi gǎnxìngqù, lìngyìfāngmiàn shì yīnwèi jiānglái xiǎng zuò guójì màoyì.","explanation":"一方面……，另一方面…… + từ mới 专业, 将来, 国际贸易."}]}],"/lessons/hsk4v3-bai-10.html":[{"point":"固定格式“说什么/怎么（着）也得×” — dù thế nào cũng phải …","items":[{"context":"“… dù thế nào cũng phải mặc áo dày một chút.”","pre":"更重要的是，说什么","blank":"也得","post":"穿上厚一点儿的衣服。","options":["也得","就得","才得"],"answer":0,"explanation":"Cấu trúc cố định: 说什么 + 也得 + V."},{"context":"“Ngày mai dù thế nào tôi cũng phải làm xong bài tập.”","pre":"假期还有两天就结束了，我明天","blank":"说什么","post":"也得把作业做完。","options":["说什么","为什么","什么时候"],"answer":0,"explanation":"说什么也得 = dù thế nào cũng phải."},{"context":"“Lần này dù thế nào cũng phải đi.”","pre":"我很后悔上次没参加这个活动，这次怎么","blank":"着","post":"也得去。","options":["着","了","过"],"answer":0,"explanation":"怎么着也得 (着 = zhe)."},{"context":"“… nếu không sẽ rét cóng đấy.” (ôn 否则 – Bài 8)","pre":"这么低的温度，你说什么也得多穿点儿，","blank":"否则","post":"会冻坏的。","options":["否则","所以","而且"],"answer":0,"explanation":"……，否则…… = nếu không thì …"},{"context":"“… phải mặc quần áo dày một chút.”","pre":"冬天去哈尔滨，说什么也得穿上","blank":"厚","post":"一点儿的衣服。","options":["厚","低","暖和"],"answer":0,"explanation":"厚一点儿的衣服 = áo dày hơn một chút."},{"type":"sort","context":"Sắp xếp: “Ngày mai dù thế nào tôi cũng phải làm xong bài tập.”","words":["我","明天","说什么","也得","把作业","做完"],"answer":"我明天说什么也得把作业做完。","explanation":"Chủ ngữ + thời gian + 说什么也得 + V."},{"type":"sort","context":"Sắp xếp: “Lần này dù thế nào tôi cũng phải đi Cáp Nhĩ Tân ngắm tuyết.”","words":["这次","我","怎么着","也得","去","哈尔滨","看雪"],"answer":"这次我怎么着也得去哈尔滨看雪。","explanation":"怎么着也得 + V."},{"type":"sort","context":"Sắp xếp: “Dù bận đến đâu, Tết tôi nhất định phải về nhà.”","words":["不管","多忙","，","春节","我","说什么也得","回家"],"answer":"不管多忙，春节我说什么也得回家。","explanation":"Ôn 不管 (Bài 8) + 说什么也得."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"妈妈生病了，我说什么也得回去看看她。","isCorrect":true,"correctVersion":"","explanation":"Đúng: 说什么也得 + V, biểu thị nhất định phải."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"他说什么也得不去。","isCorrect":false,"correctVersion":"他说什么也不去。","explanation":"Phủ định: 说什么也不 + V."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"我说什么得去参加这个活动。","isCorrect":false,"correctVersion":"我说什么也得去参加这个活动。","explanation":"Thiếu 也."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Ngày mai dù thế nào tôi cũng phải dậy sớm một chút.","answer":"明天我说什么也得早点儿起床。","answerPy":"Míngtiān wǒ shuō shénme yě děi zǎo diǎnr qǐchuáng.","explanation":"Thời gian + 说什么也得 + V."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Mùa đông đến Cáp Nhĩ Tân, dù thế nào cũng phải mặc quần áo dày.","answer":"冬天去哈尔滨，说什么也得穿厚衣服。","answerPy":"Dōngtiān qù Hā'ěrbīn, shuō shénme yě děi chuān hòu yīfu.","explanation":"说什么也得 + 穿厚衣服 (从课文1)."}]},{"point":"固定短语“有的是” — có thừa, có khối, thiếu gì","items":[{"context":"“Không sao, áo dày tớ có thừa.”","pre":"没问题，受得了，我","blank":"有的是","post":"厚衣服。","options":["有的是","有的","是有"],"answer":0,"explanation":"有的是 + N = có rất nhiều."},{"context":"“Đồ ăn ngon, đồ uống ngon có khối.”","pre":"过年时，家里有的是","blank":"好吃","post":"的、好喝的，孩子们特别开心。","options":["好吃","很多","多少"],"answer":0,"explanation":"有的是 + 好吃的、好喝的."},{"context":"“… muốn mua rau gì cũng mua được.”","pre":"这个市场特别大，有的是水果和菜，你想买什么菜","blank":"都","post":"能买到。","options":["都","才","再"],"answer":0,"explanation":"什么……都…… (đại từ phiếm chỉ, HSK 3)."},{"context":"“Đừng vội, sau này thiếu gì cơ hội.”","pre":"别着急，以后有的是","blank":"机会","post":"，这次没申请到也没关系。","options":["机会","误会","社会"],"answer":0,"explanation":"以后有的是机会 = sau này còn nhiều cơ hội."},{"context":"“Trời lạnh thế này cậu chịu nổi không?” (ôn V得了 – Bài 4)","pre":"这么冷的天气你","blank":"受","post":"得了吗？——没问题，我有的是厚衣服。","options":["受","冻","举"],"answer":0,"explanation":"受得了 / 受不了."},{"type":"sort","context":"Sắp xếp: “Tôi có thừa thời gian, có thể đi cùng bạn.”","words":["我","有的是","时间","，","可以","陪你","去"],"answer":"我有的是时间，可以陪你去。","explanation":"有的是 + N; 陪 (Bài 6)."},{"type":"sort","context":"Sắp xếp: “Chợ hoa tươi ở Quảng Châu hoa nhiều vô kể.”","words":["广州的","鲜花市场","里","有的是","花"],"answer":"广州的鲜花市场里有的是花。","explanation":"Nơi chốn + 有的是 + N."},{"type":"sort","context":"Sắp xếp: “Đừng lo, sau này thiếu gì cơ hội.”","words":["别","担心","，","以后","有的是","机会"],"answer":"别担心，以后有的是机会。","explanation":"Dùng để trấn an."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"我们学校有的是外国留学生。","isCorrect":true,"correctVersion":"","explanation":"Đúng: nơi chốn + 有的是 + N."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"我有的是很多钱。","isCorrect":false,"correctVersion":"我有的是钱。","explanation":"Không thêm 很多 sau 有的是."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"图书馆里有的是五本中文书。","isCorrect":false,"correctVersion":"图书馆里有的是中文书。","explanation":"有的是 không đi với số lượng cụ thể."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Đừng lo, ở Cáp Nhĩ Tân quần áo dày có thừa, muốn mua thì mua.","answer":"别担心，哈尔滨有的是厚衣服，想买就买。","answerPy":"Bié dānxīn, Hā'ěrbīn yǒudeshì hòu yīfu, xiǎng mǎi jiù mǎi.","explanation":"Nơi chốn + 有的是 + N."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Thời gian còn thừa, chúng ta vẫn kịp.","answer":"时间有的是，我们还来得及。","answerPy":"Shíjiān yǒudeshì, wǒmen hái láidejí.","explanation":"有的是 + 来得及 (ôn Bài 4 · điểm 4)."}]},{"point":"连词“而” — còn, mà, nhưng; (vì …) mà …","items":[{"context":"“Quảng Châu gần như không có mùa đông, còn Cáp Nhĩ Tân …”","pre":"广州基本上没有冬天，","blank":"而","post":"哈尔滨的冬天一般会从十月开始。","options":["而","和","跟"],"answer":0,"explanation":"Đối lập hai đối tượng → 而 (和 / 跟 chỉ nối danh từ)."},{"context":"“Trong những ngày căng thẳng mà hào hứng này …”","pre":"在这个紧张","blank":"而","post":"兴奋的日子里，我们都走出教室，为运动员们加油。","options":["而","也","就"],"answer":0,"explanation":"Adj + 而 + Adj (nối tiếp)."},{"context":"“… vì thời tiết ấm mà thu hút nhiều du khách.”","pre":"冬天，这个城市因为天气暖和而","blank":"吸引","post":"了很多游客。","options":["吸引","引起","举办"],"answer":0,"explanation":"因为……而 + kết quả; 吸引游客 = thu hút du khách."},{"context":"“… còn tiếng Quảng Châu khác tiếng phổ thông khá nhiều.”","pre":"哈尔滨方言和普通话听起来比较像，而广州方言和普通话","blank":"差别","post":"较大。","options":["差别","气候","方言"],"answer":0,"explanation":"差别较大 = khác biệt khá lớn."},{"context":"“Trường do thời tiết xấu mà huỷ đại hội thể thao.” (ôn 由于 – Bài 2)","pre":"学校","blank":"由于","post":"天气不好而取消了运动会。","options":["由于","虽然","如果"],"answer":0,"explanation":"由于 / 因为 + nguyên nhân + 而 + kết quả."},{"type":"sort","context":"Sắp xếp: “Miền Nam mùa đông rất ấm, còn miền Bắc mùa đông rất lạnh.”","words":["南方","冬天","很暖和","，","而","北方","冬天","很冷"],"answer":"南方冬天很暖和，而北方冬天很冷。","explanation":"A……，而 B…… (đối lập)."},{"type":"sort","context":"Sắp xếp: “Cô ấy thể hiện nhiệt tình và tích cực.”","words":["她","表现得","热情","而","积极"],"answer":"她表现得热情而积极。","explanation":"Adj + 而 + Adj; 表现 (Bài 1)."},{"type":"sort","context":"Sắp xếp: “Sân trường vì nghỉ đông mà trở nên rất yên tĩnh.”","words":["校园","因为","放寒假","而","变得","十分安静"],"answer":"校园因为放寒假而变得十分安静。","explanation":"因为……而…… (nhân quả)."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"哥哥喜欢安静，而弟弟喜欢热闹。","isCorrect":true,"correctVersion":"","explanation":"Đúng: 而 nối hai vế đối lập."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"我买了牛奶而面包。","isCorrect":false,"correctVersion":"我买了牛奶和面包。","explanation":"而 không nối hai danh từ."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"他因为生病了，而所以没来上课。","isCorrect":false,"correctVersion":"他因为生病而没来上课。","explanation":"因为……而…… đã có ý nhân quả, không thêm 所以."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Miền Nam mùa đông rất ấm, còn miền Bắc mùa đông rất lạnh.","answer":"南方冬天很暖和，而北方冬天很冷。","answerPy":"Nánfāng dōngtiān hěn nuǎnhuo, ér běifāng dōngtiān hěn lěng.","explanation":"A……，而 B…… (đối lập)."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Thành phố này vì có nhiều hoa mà được gọi là “Thành phố hoa”.","answer":"这个城市因为花多而叫“花城”。","answerPy":"Zhège chéngshì yīnwèi huā duō ér jiào “huā chéng”.","explanation":"因为……而…… (nhân quả)."}]},{"point":"频率副词“再次” — lại một lần nữa, lần thứ hai","items":[{"context":"“… chúng ta lại một lần nữa phát động hoạt động “Sống xanh”.”","pre":"今年的“世界环境日”，我们","blank":"再次","post":"开展“绿色生活”活动。","options":["再次","从来","偶尔"],"answer":0,"explanation":"再次 + V."},{"context":"“… tôi định lại đi Cáp Nhĩ Tân ngắm tuyết.”","pre":"今年冬天，我计划再次去哈尔滨","blank":"看","post":"雪。","options":["看","见","冻"],"answer":0,"explanation":"看雪 = ngắm tuyết."},{"context":"“Một lần nữa xin cảm ơn sự ủng hộ và quan tâm của quý vị!”","pre":"","blank":"再次","post":"感谢您的支持与关心！","options":["再次","再说","此外"],"answer":0,"explanation":"再次感谢 — câu trang trọng cuối thư, phát biểu."},{"context":"“Trước khi ra khỏi nhà anh ấy kiểm tra lại hành lý lần nữa.”","pre":"他出门前再次","blank":"检查","post":"了一下行李，看看东西都带好了没有。","options":["检查","举办","开展"],"answer":0,"explanation":"再次 + 检查."},{"context":"“Dù lần trước không thành công, nhưng anh ấy vẫn …” (ôn Bài 9)","pre":"尽管上次没有成功，","blank":"但是","post":"他还是决定再次试一试。","options":["但是","而且","所以"],"answer":0,"explanation":"尽管……但是……"},{"type":"sort","context":"Sắp xếp: “Chào mừng ngài lại đến chỗ chúng tôi du lịch.”","words":["欢迎","您","再次","来","我们这里","旅游"],"answer":"欢迎您再次来我们这里旅游。","explanation":"再次 + 来."},{"type":"sort","context":"Sắp xếp: “Gặp lại bạn học cũ, mọi người đều đặc biệt vui.”","words":["再次","见到","老同学","，","大家","都特别高兴"],"answer":"再次见到老同学，大家都特别高兴。","explanation":"再次 + 见到."},{"type":"sort","context":"Sắp xếp: “Trường lại tổ chức hoạt động phân loại rác.”","words":["学校","再次","举办了","垃圾分类","活动"],"answer":"学校再次举办了垃圾分类活动。","explanation":"再次 + V了 (việc đã xảy ra)."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"下个月我们会再次开展环保活动。","isCorrect":true,"correctVersion":"","explanation":"Đúng: 再次 dùng cho việc sắp làm."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"他又再次忘了带钥匙。","isCorrect":false,"correctVersion":"他再次忘了带钥匙。","explanation":"又 và 再次 trùng nghĩa — bỏ 又."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"我们再次了检查行李。","isCorrect":false,"correctVersion":"我们再次检查了行李。","explanation":"了 đặt sau động từ."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Một lần nữa cảm ơn sự giúp đỡ của mọi người!","answer":"再次感谢大家的帮助！","answerPy":"Zàicì gǎnxiè dàjiā de bāngzhù!","explanation":"再次感谢 — trang trọng."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Năm sau tôi định lại đi Quảng Châu lần nữa.","answer":"明年我打算再次去广州。","answerPy":"Míngnián wǒ dǎsuàn zàicì qù Guǎngzhōu.","explanation":"Thời gian + 打算 / 计划 + 再次 + V."}]}],"/lessons/hsk4v3-bai-2.html":[{"point":"固定格式“×就是了” — cứ … là được","items":[{"context":"“Nếu quyết định thuê thì cứ báo tôi là được.”","pre":"如果决定租了，告诉我","blank":"就是了","post":"。","options":["就是了","就是","是了"],"answer":0,"explanation":"Cấu trúc cố định: V + 就是了 (phải có 了)."},{"context":"“Tôi nhất định làm được, ông cứ yên tâm.”","pre":"我一定能办到，您","blank":"放心","post":"就是了。","options":["放心","担心","关心"],"answer":0,"explanation":"放心就是了 = cứ yên tâm."},{"context":"“Lần sau cố gắng là được.”","pre":"这次考得不好没关系，下次努力","blank":"就是了","post":"。","options":["就是了","才是了","也是了"],"answer":0,"explanation":"Đặt 就是了 ở cuối câu để động viên."},{"context":"“Bạn hài lòng thì cứ thuê luôn.” (ôn từ mới + 要是 – Bài 1)","pre":"你要是满意，","blank":"租","post":"下来就是了。","options":["租","出租","房租"],"answer":0,"explanation":"租下来 = thuê luôn; 出租 = cho thuê; 房租 = tiền thuê."},{"context":"“Phòng đã dọn xong, hôm nay bạn cứ dọn vào.”","pre":"房间已经","blank":"收拾","post":"好了，你今天搬进来就是了。","options":["收拾","入住","毕业"],"answer":0,"explanation":"收拾好了 = dọn dẹp xong."},{"type":"sort","context":"Sắp xếp: “Nếu bạn hài lòng thì cứ thuê luôn đi.”","words":["你","要是","满意","，","租下来","就是了"],"answer":"你要是满意，租下来就是了。","explanation":"要是……，V + 就是了."},{"type":"sort","context":"Sắp xếp: “Có bất kỳ vấn đề gì cứ gọi cho tôi là được.”","words":["有","任何","问题","，","给我","打电话","就是了"],"answer":"有任何问题，给我打电话就是了。","explanation":"Ôn 任何 (Bài 1) + 就是了 cuối câu."},{"type":"sort","context":"Sắp xếp: “Không biết làm cũng không sao, tôi dạy bạn là được.”","words":["不会","做","没关系","，","我","教你","就是了"],"answer":"不会做没关系，我教你就是了。","explanation":"Chủ ngữ 我 + V + 就是了."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"你别担心，我明天一定来就是了。","isCorrect":true,"correctVersion":"","explanation":"Đúng: 就是了 cuối câu, trấn an người nghe."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"这件衣服很漂亮，你买下来就是。","isCorrect":false,"correctVersion":"这件衣服很漂亮，你买下来就是了。","explanation":"Thiếu 了."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"就是了你下次努力。","isCorrect":false,"correctVersion":"你下次努力就是了。","explanation":"就是了 phải đặt cuối câu."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Nếu bạn thích thì cứ lấy đi là được.","answer":"你要是喜欢，拿走就是了。","answerPy":"Nǐ yàoshi xǐhuan, ná zǒu jiùshì le.","explanation":"要是……，V + 就是了 (ôn Bài 1 · điểm 2)."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Có bất kỳ vấn đề gì, bạn cứ hỏi tôi là được.","answer":"有任何问题，你问我就是了。","answerPy":"Yǒu rènhé wèntí, nǐ wèn wǒ jiùshì le.","explanation":"任何 (Bài 1 · điểm 1) + 就是了."}]},{"point":"转折复句“……，不过……” — …, có điều …","items":[{"context":"“Môi trường đẹp thật, có điều nghe nói gần đây có nhiều công ty.”","pre":"这个小区的环境真不错，","blank":"不过","post":"我听说，附近有十几家公司。","options":["不过","所以","而且"],"answer":0,"explanation":"Vế sau chuyển ý → 不过."},{"context":"“… có điều không thấy gấu trúc.”","pre":"我们在动物园看见了很多动物，不过","blank":"没","post":"看见大熊猫。","options":["没","不","别"],"answer":0,"explanation":"Phủ định việc đã xảy ra: 没 + V."},{"context":"“… có điều rất nhanh đã thích nghi.” (ôn từ Bài 1)","pre":"我刚来北京时还不太习惯这里的天气，不过很快就","blank":"适应","post":"了。","options":["适应","交流","申请"],"answer":0,"explanation":"适应 = thích nghi."},{"context":"“Phòng này khá sáng, có điều hơi nhỏ.”","pre":"这个房间挺","blank":"亮","post":"，不过有点儿小。","options":["亮","租","种"],"answer":0,"explanation":"挺亮 = khá sáng (tính từ)."},{"context":"“Tiền thuê không cao, có điều hơi xa công ty.”","pre":"房租不高，","blank":"不过","post":"离公司有点儿远。","options":["不过","因为","并且"],"answer":0,"explanation":"Khen trước, góp ý sau → 不过."},{"type":"sort","context":"Sắp xếp: “Chiếc điện thoại này cũng được, có điều hơi đắt.”","words":["这个手机","还可以","，","不过","有点儿贵"],"answer":"这个手机还可以，不过有点儿贵。","explanation":"……，不过 + ý chuyển."},{"type":"sort","context":"Sắp xếp: “Nhà rất đẹp, có điều xung quanh không yên tĩnh lắm.”","words":["房子","很漂亮","，","不过","周围","不太安静"],"answer":"房子很漂亮，不过周围不太安静。","explanation":"不过 đứng trước chủ ngữ vế sau (周围)."},{"type":"sort","context":"Sắp xếp: “Tôi rất muốn đi, có điều e là không có thời gian.”","words":["我","很想去","，","不过","恐怕","没有时间"],"answer":"我很想去，不过恐怕没有时间。","explanation":"不过 + 恐怕 (từ mới bài này)."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"这个小区很安静，不过环境也很好。","isCorrect":false,"correctVersion":"这个小区很安静，而且环境也很好。","explanation":"Hai ý cùng chiều tốt → dùng 而且, không dùng 不过."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"天气预报说明天是晴天，不过可能会刮风。","isCorrect":true,"correctVersion":"","explanation":"Đúng: trời nắng (tốt) — có điều có gió (chưa tốt)."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"不过他很忙，他每天都去跑步。","isCorrect":false,"correctVersion":"他很忙，不过每天都去跑步。","explanation":"不过 đứng ở đầu vế SAU."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Căn nhà này vị trí rất tốt, có điều tiền thuê hơi đắt.","answer":"这个房子位置很好，不过房租有点儿贵。","answerPy":"Zhège fángzi wèizhì hěn hǎo, búguò fángzū yǒudiǎnr guì.","explanation":"位置, 房租 (từ mới) + 不过."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Tôi rất muốn đi du lịch, có điều e là không có thời gian.","answer":"我很想去旅游，不过恐怕没有时间。","answerPy":"Wǒ hěn xiǎng qù lǚyóu, búguò kǒngpà méiyǒu shíjiān.","explanation":"不过 + 恐怕."}]},{"point":"连词/副词“并” — và, đồng thời; hoàn toàn (không)","items":[{"context":"“… và chỉ cho tôi cách dùng.”","pre":"房东又向我介绍了一下房子里的东西，","blank":"并","post":"告诉我这些东西怎么用。","options":["并","和","跟"],"answer":0,"explanation":"Nối hai cụm động từ → 并 (和 nối danh từ)."},{"context":"“… lần thuê nhà này chẳng hề dễ.”","pre":"对白家月来说，这次租房并","blank":"不","post":"容易。","options":["不","没","很"],"answer":0,"explanation":"并不 + tính từ."},{"context":"“… và xin được học bổng.” (ôn từ Bài 1)","pre":"她考上了北京大学并申请到了","blank":"奖学金","post":"。","options":["奖学金","房租","工资"],"answer":0,"explanation":"申请到 + 奖学金."},{"context":"“Tôi đâu có đồng ý thuê ngay …”","pre":"我","blank":"并","post":"没有答应你就租这个房子，我还要再想想。","options":["并","也","就"],"answer":0,"explanation":"并没有 = phủ định mạnh, phản bác."},{"context":"“Học chữ Hán chẳng khó, cứ viết nhiều luyện nhiều là được.” (ôn 就是了 – điểm 1)","pre":"学汉字","blank":"并","post":"不难，多写多练就是了。","options":["并","和","还"],"answer":0,"explanation":"并不难 = chẳng khó chút nào."},{"type":"sort","context":"Sắp xếp: “Tốt nghiệp xong anh ấy đến Bắc Kinh làm việc, và thuê một căn nhà gần công ty.”","words":["他","毕业后","来北京工作","，","并","在公司附近","租了个房子"],"answer":"他毕业后来北京工作，并在公司附近租了个房子。","explanation":"V1……，并 + V2……"},{"type":"sort","context":"Sắp xếp: “Khu chung cư này chẳng yên tĩnh chút nào.”","words":["这个","小区","并","不","安静"],"answer":"这个小区并不安静。","explanation":"并不 + Adj."},{"type":"sort","context":"Sắp xếp: “Chúng tôi đã thảo luận vấn đề này và đưa ra quyết định.”","words":["我们","讨论了","这个问题","，","并","做出了","决定"],"answer":"我们讨论了这个问题，并做出了决定。","explanation":"Hai hành động nối tiếp, cùng chủ ngữ."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"我买了苹果并香蕉。","isCorrect":false,"correctVersion":"我买了苹果和香蕉。","explanation":"并 không nối hai danh từ."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"其实这个问题并不难。","isCorrect":true,"correctVersion":"","explanation":"Đúng: 并不 phản bác suy nghĩ “khó”."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"在北京租房子不并容易。","isCorrect":false,"correctVersion":"在北京租房子并不容易。","explanation":"Thứ tự đúng: 并不."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Cô ấy tìm được việc làm và thuê một căn nhà gần công ty.","answer":"她找到了工作，并在公司附近租了一个房子。","answerPy":"Tā zhǎo dào le gōngzuò, bìng zài gōngsī fùjìn zū le yí gè fángzi.","explanation":"并 nối hai hành động, không lặp chủ ngữ."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Thực ra thuê nhà ở Bắc Kinh chẳng hề rẻ.","answer":"其实在北京租房子并不便宜。","answerPy":"Qíshí zài Běijīng zū fángzi bìng bú piányi.","explanation":"并不 + Adj: phản bác suy nghĩ “rẻ”."}]},{"point":"连词/介词“由于” — do, bởi vì","items":[{"context":"“Do trời mưa to suốt, nên …”","pre":"","blank":"由于","post":"一直下大雨，所以我们决定不爬山了。","options":["由于","虽然","要是"],"answer":0,"explanation":"由于……，所以…… (nhân quả)."},{"context":"“… nên lúc đầu họ cũng không mua nhà.”","pre":"由于很多刚工作的年轻人工资还不太高，","blank":"所以","post":"他们一开始也不买房。","options":["所以","但是","而且"],"answer":0,"explanation":"Vế sau của 由于 dùng 所以 / 因此."},{"context":"“Nhờ sự nỗ lực của mọi người …”","pre":"由于大家的","blank":"努力","post":"，这次运动会我们班获得了第一名。","options":["努力","房租","位置"],"answer":0,"explanation":"Giới từ: 由于 + danh từ."},{"context":"“… vì vậy nhiều người thích thuê nhà ở đây.”","pre":"由于这个小区很安静，房子价格也不高，","blank":"因此","post":"，很多人都喜欢在这里租房子。","options":["因此","不过","并"],"answer":0,"explanation":"由于……，因此…… (因此 yīncǐ = vì vậy)."},{"context":"“… cô ấy quyết định thuê nhà gần công ty.”","pre":"由于新公司离她住的地方比较远，她决定在公司","blank":"附近","post":"租个房子。","options":["附近","价格","信息"],"answer":0,"explanation":"在 + nơi + 附近 = ở gần …"},{"type":"sort","context":"Sắp xếp: “Do điện thoại hết pin, cô ấy không có cách nào gọi điện.”","words":["由于","手机","没电了","，","她","没有办法","打电话"],"answer":"由于手机没电了，她没有办法打电话。","explanation":"由于 + nguyên nhân，kết quả."},{"type":"sort","context":"Sắp xếp: “Do lương không cao lắm nên anh ấy chọn thuê nhà.”","words":["由于","工资","不太高","，","所以","他","选择租房"],"answer":"由于工资不太高，所以他选择租房。","explanation":"由于……，所以……"},{"type":"sort","context":"Sắp xếp: “Nhờ sự giúp đỡ của mọi người, chúng tôi đã nhanh chóng hoàn thành công việc.”","words":["由于","大家的","帮助","，","我们","很快就","完成了工作"],"answer":"由于大家的帮助，我们很快就完成了工作。","explanation":"Giới từ: 由于 + cụm danh từ."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"由于天气不好，所以飞机晚到了两个小时。","isCorrect":true,"correctVersion":"","explanation":"Đúng: 由于……，所以……"},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"由于下雨，但是比赛没有停。","isCorrect":false,"correctVersion":"虽然下雨，但是比赛没有停。","explanation":"Đây là quan hệ nhượng bộ → 虽然……但是……; 由于 chỉ nguyên nhân."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"我没去上课，由于我生病了。","isCorrect":false,"correctVersion":"由于我生病了，所以没去上课。","explanation":"由于 đứng ở vế trước."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Do lương còn chưa cao nên nhiều người trẻ chọn thuê nhà.","answer":"由于工资还不太高，所以很多年轻人选择租房。","answerPy":"Yóuyú gōngzī hái bú tài gāo, suǒyǐ hěn duō niánqīngrén xuǎnzé zū fáng.","explanation":"由于……，所以…… + từ mới 工资."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Nhờ sự giúp đỡ của Lý Văn, Bạch Gia Nguyệt đã thuê được căn nhà phù hợp.","answer":"由于李文的帮助，白家月租到了合适的房子。","answerPy":"Yóuyú Lǐ Wén de bāngzhù, Bái Jiāyuè zū dào le héshì de fángzi.","explanation":"Giới từ: 由于 + cụm danh từ."}]}],"/lessons/hsk4v3-bai-3.html":[{"point":"转折复句“……×是×，就是/不过……” — … thì … thật, nhưng / chỉ là …","items":[{"context":"“Bắc Kinh to thì to thật, nhưng …”","pre":"北京大是","blank":"大","post":"，不过这边的路基本上都是正南正北的。","options":["大","很大","太大"],"answer":0,"explanation":"Hai bên 是 lặp lại đúng một từ: 大是大."},{"context":"“Căn nhà này rẻ thì rẻ thật, chỉ là cách công ty xa quá.”","pre":"这个房子便宜是便宜，","blank":"就是","post":"离我的公司太远了。","options":["就是","所以","因为"],"answer":0,"explanation":"Vế sau dùng 就是 / 不过 chỉ ra hạn chế."},{"context":"“Chúng tôi nghĩ thì có nghĩ rồi …”","pre":"我们想是","blank":"想","post":"了，就是没想出更好的办法。","options":["想","想想","想到"],"answer":0,"explanation":"想是想了 — 了 ở cuối khung."},{"context":"“… chỉ là dễ tiêu tiền lung tung.” (ôn từ mới)","pre":"网购方便是方便，就是容易","blank":"乱","post":"花钱。","options":["乱","正","直接"],"answer":0,"explanation":"乱花钱 = tiêu tiền lung tung."},{"context":"“Mát thì mát rồi, có điều mùa hè chưa hết …”","pre":"凉快是凉快了，","blank":"不过","post":"夏天还没结束，过几天又会热起来了。","options":["不过","于是","甚至"],"answer":0,"explanation":"×是×，不过……"},{"type":"sort","context":"Sắp xếp: “Cái áo này đẹp thì đẹp thật, chỉ là hơi đắt.”","words":["这件衣服","好看","是","好看","，","就是","有点儿贵"],"answer":"这件衣服好看是好看，就是有点儿贵。","explanation":"A是A，就是……"},{"type":"sort","context":"Sắp xếp: “Phần mềm này tiện thì tiện thật, nhưng tôi vẫn chưa biết dùng lắm.”","words":["这个软件","方便","是","方便","，","不过","我还不太会用"],"answer":"这个软件方便是方便，不过我还不太会用。","explanation":"A是A，不过……"},{"type":"sort","context":"Sắp xếp: “Bài tập viết xong thì viết xong rồi, nhưng có câu không biết làm.”","words":["作业","写完","是","写完了","，","不过","有的题","不会写"],"answer":"作业写完是写完了，不过有的题不会写。","explanation":"Cụm động từ: 写完是写完了."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"北京大是很大，不过路很好找。","isCorrect":false,"correctVersion":"北京大是大，不过路很好找。","explanation":"Hai bên 是 giống hệt nhau, không thêm 很."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"这家饭馆的菜好吃是好吃，就是价格有点儿高。","isCorrect":true,"correctVersion":"","explanation":"Đúng: A是A，就是……"},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"我累是累，所以还想再学一会儿。","isCorrect":false,"correctVersion":"我累是累，不过还想再学一会儿。","explanation":"Vế sau là chuyển ngoặt → 不过 / 就是, không dùng 所以."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Điện thoại này đẹp thì đẹp thật, chỉ là hơi đắt.","answer":"这个手机好看是好看，就是有点儿贵。","answerPy":"Zhège shǒujī hǎokàn shì hǎokàn, jiù shì yǒudiǎnr guì.","explanation":"A是A，就是 / 不过……"},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Tôi muốn đi thì muốn thật, có điều hôm nay không có thời gian.","answer":"我想去是想去，不过今天没有时间。","answerPy":"Wǒ xiǎng qù shì xiǎng qù, búguò jīntiān méiyǒu shíjiān.","explanation":"Cụm động từ 想去是想去."}]},{"point":"递进复句“不仅/不光……，还/而且……” — không những … mà còn …","items":[{"context":"“Giờ tôi không những biết quét mã thanh toán …”","pre":"现在我","blank":"不仅","post":"会扫码结账，还会用手机在网上购物了。","options":["不仅","虽然","要是"],"answer":0,"explanation":"不仅……，还……"},{"context":"“… mà còn đưa chúng tôi tìm hiểu văn hóa.”","pre":"王老师不光教我们说中文，","blank":"而且","post":"带我们了解中国文化。","options":["而且","但是","所以"],"answer":0,"explanation":"不光……，而且……"},{"context":"“… mà còn bán cà phê và trà sữa.”","pre":"现在很多书店不仅卖书，","blank":"还","post":"卖咖啡和奶茶。","options":["还","就","才"],"answer":0,"explanation":"还 đứng ngay trước động từ 卖."},{"context":"“… mà còn gửi được chuyển phát nhanh.” (ôn từ mới)","pre":"这个软件不仅能支付，还能","blank":"寄","post":"快递。","options":["寄","管","转"],"answer":0,"explanation":"寄快递 = gửi chuyển phát nhanh."},{"context":"“… mà giao hàng còn nhanh.”","pre":"在中国网购，不仅选择多、价格不高，","blank":"而且","post":"送货很快。","options":["而且","于是","不过"],"answer":0,"explanation":"不仅……，而且……"},{"type":"sort","context":"Sắp xếp: “Cô ấy không những biết hát bài tiếng Trung, mà còn hát rất hay.”","words":["她","不仅","会唱","中文歌","，","而且","唱得很好"],"answer":"她不仅会唱中文歌，而且唱得很好。","explanation":"Chủ ngữ + 不仅……，而且……"},{"type":"sort","context":"Sắp xếp: “Tôi không những biết quét mã thanh toán, mà còn biết mua online.”","words":["我","不仅","会","扫码结账","，","还","会","网购"],"answer":"我不仅会扫码结账，还会网购。","explanation":"还 + 会 + V."},{"type":"sort","context":"Sắp xếp: “Quán này không những món ngon mà giá cũng không cao.”","words":["这家饭馆","不光","菜好吃","，","而且","价格","也不高"],"answer":"这家饭馆不光菜好吃，而且价格也不高。","explanation":"而且……也……"},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"不仅他会说中文，还会说英文。","isCorrect":false,"correctVersion":"他不仅会说中文，还会说英文。","explanation":"Cùng chủ ngữ → chủ ngữ đứng trước 不仅."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"现在很多书店不仅卖书，还卖咖啡和奶茶。","isCorrect":true,"correctVersion":"","explanation":"Đúng: chủ ngữ + 不仅……，还……"},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"她不仅很漂亮，但是很聪明。","isCorrect":false,"correctVersion":"她不仅很漂亮，而且很聪明。","explanation":"不仅 đi với 而且 / 还, không đi với 但是."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Thanh toán bằng điện thoại không những nhanh mà còn rất tiện.","answer":"用手机支付不仅很快，而且很方便。","answerPy":"Yòng shǒujī zhīfù bùjǐn hěn kuài, érqiě hěn fāngbiàn.","explanation":"不仅……，而且 / 还……"},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Cậu ấy không những giúp tôi tải WeChat, mà còn dạy tôi cách dùng.","answer":"他不仅帮我下载了微信，还教我怎么用。","answerPy":"Tā bùjǐn bāng wǒ xiàzài le Wēixìn, hái jiào wǒ zěnme yòng.","explanation":"Chủ ngữ 他 đứng trước 不仅."}]},{"point":"连词“甚至” — thậm chí, ngay cả","items":[{"context":"“… nhiều du học sinh thậm chí đã thay đổi thói quen mua sắm.”","pre":"在中国网购，送货很快，很多留学生","blank":"甚至","post":"改变了自己的购物习惯。","options":["甚至","不仅","于是"],"answer":0,"explanation":"甚至 + V: nhấn mạnh điều vượt dự đoán."},{"context":"“Tàu cao tốc nhanh thật, thậm chí chưa nhìn rõ …”","pre":"高铁速度真快，","blank":"甚至","post":"还没看清楚，它就已经开过去了。","options":["甚至","虽然","要是"],"answer":0,"explanation":"甚至 đứng trước phần được nhấn mạnh."},{"context":"“… thậm chí còn có một siêu thị.”","pre":"这个小区真不错，有小花园、球场，甚至","blank":"还","post":"有一个超市。","options":["还","就","才"],"answer":0,"explanation":"甚至还 + 有……"},{"context":"“… thậm chí ngay cả thời gian ăn cơm cũng không có.”","pre":"他太忙了，甚至","blank":"连","post":"吃饭的时间都没有。","options":["连","把","被"],"answer":0,"explanation":"甚至连……都……"},{"context":"“… thậm chí nhiều người nổi tiếng cũng đến uống.”","pre":"这家咖啡店很有名，甚至很多","blank":"名人","post":"都会来喝咖啡。","options":["名人","手指","现金"],"answer":0,"explanation":"名人 = người nổi tiếng."},{"type":"sort","context":"Sắp xếp: “Anh ấy hiểu tôi quá, thậm chí tôi chưa nói anh ấy đã biết tôi muốn làm gì.”","words":["他","太了解我了","，","甚至","我还没说话","，","他就知道","我想做什么"],"answer":"他太了解我了，甚至我还没说话，他就知道我想做什么。","explanation":"甚至 + câu ngắn (还没……就……)."},{"type":"sort","context":"Sắp xếp: “Khu này có vườn hoa, sân bóng, thậm chí còn có một siêu thị.”","words":["这个小区","有小花园、球场","，","甚至","还有","一个超市"],"answer":"这个小区有小花园、球场，甚至还有一个超市。","explanation":"Liệt kê: 甚至 trước mục cuối."},{"type":"sort","context":"Sắp xếp: “Anh ấy bận đến mức thậm chí quên cả ăn cơm.”","words":["他","忙得","甚至","连饭","都","忘了吃"],"answer":"他忙得甚至连饭都忘了吃。","explanation":"V得 + 甚至连……都……"},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"甚至在中国寄快递很快。","isCorrect":false,"correctVersion":"在中国寄快递特别快，甚至上午寄出下午就收到了。","explanation":"甚至 không mở đầu câu; phần sau 甚至 phải vượt dự đoán."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"他中文说得很好，甚至能看懂中文报纸。","isCorrect":true,"correctVersion":"","explanation":"Đúng: đọc hiểu báo là mức cao hơn nói tốt."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"他每天起得很早，甚至七点起床。","isCorrect":false,"correctVersion":"他每天起得很早，甚至五点就起床了。","explanation":"Phần sau 甚至 phải nổi bật hơn hẳn; 7 giờ không “sớm” đến mức bất ngờ, thêm 就……了 nhấn mạnh."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Ở Trung Quốc mọi người đều dùng điện thoại trả tiền, thậm chí mua một chai nước cũng quét mã.","answer":"在中国大家都用手机支付，甚至买一瓶水也扫码。","answerPy":"Zài Zhōngguó dàjiā dōu yòng shǒujī zhīfù, shènzhì mǎi yì píng shuǐ yě sǎomǎ.","explanation":"甚至 + phần bất ngờ + 也 / 都."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Anh ấy bận lắm, thậm chí cuối tuần cũng phải đi làm.","answer":"他很忙，甚至周末也要上班。","answerPy":"Tā hěn máng, shènzhì zhōumò yě yào shàngbān.","explanation":"甚至 + 周末也……"}]},{"point":"承接复句“……，于是……” — …, thế là …","items":[{"context":"“… thế là có người nói ra nỗi lo trên mạng.”","pre":"我们担心个人信息能否得到保护，","blank":"于是","post":"有人在网上说出了自己的担心。","options":["于是","甚至","不仅"],"answer":0,"explanation":"于是 đứng đầu vế sau."},{"context":"“… thế là lên đại học chọn học y.”","pre":"她从小就想当医生，于是上大学时就选择了学","blank":"医","post":"。","options":["医","法律","技术"],"answer":0,"explanation":"学医 = học y; 当医生 ôn Bài 1."},{"context":"“… quyết định khỏi bệnh sẽ tập thể dục.”","pre":"最近总感冒，于是他决定病好后就开始","blank":"锻炼","post":"身体。","options":["锻炼","保护","改变"],"answer":0,"explanation":"锻炼身体 = rèn luyện thân thể (HSK 3)."},{"context":"“… thế là tôi cũng không muốn nói nữa.”","pre":"大家都不说话，于是我","blank":"也","post":"不想说话了。","options":["也","才","再"],"answer":0,"explanation":"于是 + chủ ngữ + 也……"},{"context":"“… thế là tôi đi thư viện một mình.” (综合练习 3)","pre":"在十字路口等了半个小时，他们也没来，","blank":"于是","post":"我就一个人去图书馆了。","options":["于是","而且","甚至"],"answer":0,"explanation":"于是……就……"},{"type":"sort","context":"Sắp xếp: “Tôi rất mệt, thế là về nhà nghỉ.”","words":["我","很累","，","于是","就","回家","休息了"],"answer":"我很累，于是就回家休息了。","explanation":"……，于是就……"},{"type":"sort","context":"Sắp xếp: “Anh ấy không thạo đường, thế là hỏi đường một bạn học.”","words":["他","不熟悉路","，","于是","向","一位同学","问路"],"answer":"他不熟悉路，于是向一位同学问路。","explanation":"于是 + 向 + ai + V."},{"type":"sort","context":"Sắp xếp: “Điện thoại hết pin, thế là tôi trả bằng tiền mặt.”","words":["手机没电了","，","于是","我","用现金","结了账"],"answer":"手机没电了，于是我用现金结了账。","explanation":"于是 + chủ ngữ 我 + V."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"于是天黑了，我们回家了。","isCorrect":false,"correctVersion":"天黑了，于是我们回家了。","explanation":"于是 đứng đầu vế sau."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"他想学好中文，于是来中国留学了。","isCorrect":true,"correctVersion":"","explanation":"Đúng: việc trước dẫn đến việc sau, đã xảy ra."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"天冷了，于是你多穿点儿衣服吧。","isCorrect":false,"correctVersion":"天冷了，你多穿点儿衣服吧。","explanation":"Câu khuyên → không dùng 于是 (có thể dùng 所以)."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Tôi không biết dùng WeChat, thế là bạn Trung Quốc dạy tôi.","answer":"我不会用微信，于是中国朋友教我。","answerPy":"Wǒ bú huì yòng Wēixìn, yúshì Zhōngguó péngyou jiào wǒ.","explanation":"……，于是……"},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Mua online quá tiện, thế là cô ấy hay tiêu tiền lung tung.","answer":"网购太方便了，于是她常常乱花钱。","answerPy":"Wǎnggòu tài fāngbiàn le, yúshì tā chángcháng luàn huā qián.","explanation":"于是 + chủ ngữ + V; từ mới 网购, 乱."}]}],"/lessons/hsk4v3-bai-4.html":[{"point":"可能补语“动词+得/不+了” — làm được / không làm được","items":[{"context":"“Điện thoại không có sóng, không lên mạng được.”","pre":"手机没有信号，上","blank":"不了","post":"网。","options":["不了","得了","不能"],"answer":0,"explanation":"上网 là từ ly hợp → 上不了网."},{"context":"“Hôm nay cô ấy không đến được nữa.”","pre":"她刚才给我发信息，说她今天来","blank":"不了","post":"了。","options":["不了","得了","没有"],"answer":0,"explanation":"来不了 = không đến được; 了 cuối câu báo sự thay đổi."},{"context":"“… có tham gia được không?”","pre":"明天的足球比赛，你们班男生参加","blank":"得了","post":"吗？","options":["得了","了得","得不"],"answer":0,"explanation":"Hỏi khả năng: V + 得了 + 吗？"},{"context":"“Món gọi không nhiều, ăn hết được.”","pre":"咱们点的菜不多，吃","blank":"得了","post":"。","options":["得了","不了","了"],"answer":0,"explanation":"菜不多 → 吃得了 (ăn hết được)."},{"context":"“Mất ví rồi, không mua được vé tàu điện ngầm.”","pre":"我的钱包丢了，买","blank":"不了","post":"地铁票了。","options":["不了","得了","不能"],"answer":0,"explanation":"买不了 + tân ngữ."},{"type":"sort","context":"Sắp xếp: “Điện thoại không có sóng, tôi không lên mạng được.”","words":["手机","没有信号","，","我","上不了","网"],"answer":"手机没有信号，我上不了网。","explanation":"上 + 不了 + 网."},{"type":"sort","context":"Sắp xếp: “Mai bạn có đến được không?”","words":["明天","你","来得了","来不了","？"],"answer":"明天你来得了来不了？","explanation":"Câu hỏi chính phản: V得了V不了？"},{"type":"sort","context":"Sắp xếp: “Nhiều món thế này, chúng mình ăn hết được không?”","words":["这么多","菜","，","咱们","吃得了","吗","？"],"answer":"这么多菜，咱们吃得了吗？","explanation":"V得了吗？"},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"我今天有点儿事，去不了你家了。","isCorrect":true,"correctVersion":"","explanation":"Đúng: 去不了 + nơi chốn + 了."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"雨太大了，我们出门不了。","isCorrect":false,"correctVersion":"雨太大了，我们出不了门。","explanation":"出门 là từ ly hợp: 出不了门."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"他病了，明天不能来不了。","isCorrect":false,"correctVersion":"他病了，明天来不了。","explanation":"Bỏ 不能 — không phủ định hai lần."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Điện thoại tôi hết pin rồi, không quét mã được.","answer":"我的手机没电了，扫不了码。","answerPy":"Wǒ de shǒujī méi diàn le, sǎo bù le mǎ.","explanation":"扫码 là từ ly hợp → 扫不了码."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Bài tập nhiều thế này, một ngày bạn làm xong được không?","answer":"这么多作业，你一天做得了吗？","answerPy":"Zhème duō zuòyè, nǐ yì tiān zuò de liǎo ma?","explanation":"V得了吗？ hỏi khả năng hoàn thành."}]},{"point":"连词“再说” — vả lại, hơn nữa","items":[{"context":"“… vả lại hàng xóm với nhau phải giúp nhau.”","pre":"我提着这些东西就算锻炼身体了，","blank":"再说","post":"邻居之间就是要互相帮助啊。","options":["再说","不过","于是"],"answer":0,"explanation":"再说 bổ sung lý do thứ hai."},{"context":"“… vả lại ngoài trời vẫn đang mưa đấy.”","pre":"今天太晚了，别去超市了，再说外面还在下雨","blank":"呢","post":"。","options":["呢","吗","吧"],"answer":0,"explanation":"还在 + V + 呢: sự việc đang tiếp diễn (HSK 2/3)."},{"context":"“… vả lại đông người cũng vui hơn.”","pre":"你今天正好有时间，再说人多","blank":"也","post":"更热闹。","options":["也","就","才"],"answer":0,"explanation":"Vế 再说 hay có 也 / 还."},{"context":"“… coi như là tập thể dục rồi.” (ôn từ mới)","pre":"我提着这些东西就","blank":"算","post":"锻炼身体了。","options":["算","像","变"],"answer":0,"explanation":"就算……了 = coi như là."},{"context":"“… vả lại bạn đã có nhiều áo rồi.”","pre":"别买这件了，太贵了，","blank":"再说","post":"你已经有很多衣服了。","options":["再说","不过","甚至"],"answer":0,"explanation":"Hai lý do cùng chiều (đắt + đã có nhiều) → 再说."},{"type":"sort","context":"Sắp xếp: “Hôm nay muộn quá rồi, vả lại ngoài trời vẫn đang mưa.”","words":["今天","太晚了","，","再说","外面","还在下雨呢"],"answer":"今天太晚了，再说外面还在下雨呢。","explanation":"Lý do 1，再说 + lý do 2."},{"type":"sort","context":"Sắp xếp: “Căn nhà này gần trường, vả lại tiền thuê cũng không đắt.”","words":["这个房子","离学校很近","，","再说","房租","也不贵"],"answer":"这个房子离学校很近，再说房租也不贵。","explanation":"再说 + chủ ngữ + 也 + …"},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"咱们打车去吧，时间不多了，再说东西也很多。","isCorrect":true,"correctVersion":"","explanation":"Đúng: hai lý do cùng chiều (ít thời gian + nhiều đồ) → đi taxi."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"这件衣服很漂亮，再说太贵了，我不买了。","isCorrect":false,"correctVersion":"这件衣服很漂亮，不过太贵了，我不买了。","explanation":"Hai ý trái chiều → dùng 不过 (Bài 2 · điểm 2)."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"再说外面很冷，你别出去了。","isCorrect":false,"correctVersion":"已经很晚了，再说外面很冷，你别出去了。","explanation":"再说 không mở đầu khi chưa có lý do thứ nhất."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Chúng mình đi tàu điện ngầm đi, nhanh, vả lại cũng không đắt.","answer":"咱们坐地铁去吧，很快，再说也不贵。","answerPy":"Zánmen zuò dìtiě qù ba, hěn kuài, zàishuō yě bú guì.","explanation":"Lý do 1，再说 + 也 + lý do 2."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Đừng khách sáo, việc này rất đơn giản, vả lại hàng xóm với nhau nên giúp đỡ lẫn nhau.","answer":"别客气，这件事很简单，再说邻居之间应该互相帮助。","answerPy":"Bié kèqi, zhè jiàn shì hěn jiǎndān, zàishuō línjū zhījiān yīnggāi hùxiāng bāngzhù.","explanation":"再说 + từ mới 之间, 互相."}]},{"point":"并列复句“既……，又/也……” — vừa … vừa …","items":[{"context":"“Cô ấy thấy như vậy vừa tiện, vừa …”","pre":"她觉得这样","blank":"既","post":"方便，又能锻炼身体。","options":["既","也","还"],"answer":0,"explanation":"Vế đầu dùng 既."},{"context":"“… vừa ngon vừa rẻ.”","pre":"这家饭馆的菜既好吃，","blank":"又","post":"便宜。","options":["又","再","就"],"answer":0,"explanation":"既……又……"},{"context":"“… cũng học được kiến thức lịch sử.”","pre":"我很喜欢这门课程，既能提高中文水平，","blank":"也","post":"能学到历史知识。","options":["也","都","才"],"answer":0,"explanation":"既……也…… (vế sau là cụm động từ)."},{"context":"“… lại còn bảo vệ được môi trường.”","pre":"她觉得骑车既方便，又能锻炼身体，","blank":"还","post":"能保护环境。","options":["还","既","就"],"answer":0,"explanation":"Ý thứ ba dùng 还."},{"context":"“… sạc điện cũng rất tiện.” (ôn từ mới)","pre":"电动车速度快，价格不高，","blank":"充电","post":"也很方便。","options":["充电","速度","力气"],"answer":0,"explanation":"充电 = sạc điện."},{"type":"sort","context":"Sắp xếp: “Món ăn ở nhà hàng này vừa ngon vừa rẻ.”","words":["这家","饭馆的菜","既","好吃","又","便宜"],"answer":"这家饭馆的菜既好吃又便宜。","explanation":"Chủ ngữ + 既 + A + 又 + B."},{"type":"sort","context":"Sắp xếp: “Đi xe đạp vừa rèn luyện thân thể, cũng bảo vệ được môi trường.”","words":["骑自行车","既","能锻炼身体","，","也","能保护环境"],"answer":"骑自行车既能锻炼身体，也能保护环境。","explanation":"既……也……"},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"他既是我的老师，也是我的朋友。","isCorrect":true,"correctVersion":"","explanation":"Đúng: 既是……也是……"},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"既他会说汉语，又他会说英语。","isCorrect":false,"correctVersion":"他既会说汉语，又会说英语。","explanation":"既 / 又 đứng sau chủ ngữ."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"这件衣服既漂亮，又不好看。","isCorrect":false,"correctVersion":"这件衣服既漂亮，又便宜。","explanation":"Hai ý mâu thuẫn — phải cùng chiều."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Xe điện vừa nhanh vừa rẻ, nên ngày càng thịnh hành.","answer":"电动车既快又便宜，所以越来越流行。","answerPy":"Diàndòngchē jì kuài yòu piányi, suǒyǐ yuèláiyuè liúxíng.","explanation":"既……又…… + 流行."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Đi tàu điện ngầm vừa không bị tắc đường, vừa tiết kiệm được thời gian.","answer":"坐地铁既不堵车，又能省时间。","answerPy":"Zuò dìtiě jì bù dǔchē, yòu néng shěng shíjiān.","explanation":"既……又 / 也…… + 省."}]},{"point":"固定短语“来得及/来不及” — kịp / không kịp","items":[{"context":"“Người không kịp ăn sáng …”","pre":"没","blank":"来得及","post":"吃早饭的人在这里就能买到热包子。","options":["来得及","来不及","不来及"],"answer":0,"explanation":"没来得及 + V (✗ 没来不及)."},{"context":"“… tôi không kịp thông báo cho mọi người nữa.”","pre":"你现在才告诉我，我","blank":"来不及","post":"通知大家了。","options":["来不及","来得及","没来得及"],"answer":0,"explanation":"来不及 + V + 了."},{"context":"“… 9 giờ xuất phát có kịp không?”","pre":"中午12点的飞机，咱们9点出发","blank":"来得及","post":"吗？","options":["来得及","来不及了","没来得及"],"answer":0,"explanation":"Hỏi: ……来得及吗？"},{"context":"“… kịp ăn sáng.”","pre":"别着急，还有15分钟，咱们来得及吃","blank":"早饭","post":"。","options":["早饭","速度","乘客"],"answer":0,"explanation":"来得及 + V + O."},{"context":"“… bạn không kịp đi tàu điện ngầm về nữa …”","pre":"时间太晚了，你","blank":"来不及","post":"坐地铁回去了，就住在我们这儿吧。","options":["来不及","来得及","没来得及"],"answer":0,"explanation":"来不及 + V + 了."},{"type":"sort","context":"Sắp xếp: “Còn nửa tiếng, chúng mình kịp ăn sáng.”","words":["还有","半个小时","，","咱们","来得及","吃早饭"],"answer":"还有半个小时，咱们来得及吃早饭。","explanation":"来得及 + V."},{"type":"sort","context":"Sắp xếp: “Sáng nay tôi chưa kịp ăn sáng đã đi làm rồi.”","words":["我","早上","没来得及","吃早饭","就","去上班了"],"answer":"我早上没来得及吃早饭就去上班了。","explanation":"没来得及 + V + 就……了."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"现在出发还来得及。","isCorrect":true,"correctVersion":"","explanation":"Đúng: 还来得及 = vẫn còn kịp."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"昨天我没来不及跟你说再见。","isCorrect":false,"correctVersion":"昨天我没来得及跟你说再见。","explanation":"Việc đã qua: 没来得及."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"飞机十点起飞，现在已经九点半了，来得及不了。","isCorrect":false,"correctVersion":"飞机十点起飞，现在已经九点半了，来不及了。","explanation":"Phủ định là 来不及, không có 来得及不了."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Sáng nay tôi dậy muộn, không kịp ăn sáng.","answer":"今天早上我起晚了，没来得及吃早饭。","answerPy":"Jīntiān zǎoshang wǒ qǐ wǎn le, méi láidejí chī zǎofàn.","explanation":"Việc đã qua → 没来得及 + V."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Phim 8 giờ bắt đầu, bây giờ đi còn kịp không?","answer":"电影八点开始，现在去还来得及吗？","answerPy":"Diànyǐng bā diǎn kāishǐ, xiànzài qù hái láidejí ma?","explanation":"……，来得及吗？"}]}],"/lessons/hsk4v3-bai-5.html":[{"point":"范围副词“至少” — ít nhất, tối thiểu","items":[{"context":"“Cháu sang Trung Quốc ít nhất hai tháng rồi …”","pre":"家月，你来中国","blank":"至少","post":"两个月了，习惯吃中餐了吗？","options":["至少","专门","任何"],"answer":0,"explanation":"至少 + cụm thời gian."},{"context":"“Mỗi năm có ít nhất hai trăm du học sinh …”","pre":"每年至少","blank":"有","post":"两百名留学生来我校学习中文专业。","options":["有","是","在"],"answer":0,"explanation":"至少 + 有 + số lượng."},{"context":"“Tuy chưa gặp mặt, nhưng ít ra cũng đã trò chuyện trên mạng nhiều lần.”","pre":"我们虽然没有见过面，","blank":"但","post":"至少在网上聊过很多次。","options":["但","就","于是"],"answer":0,"explanation":"虽然……，但至少…… — ôn 虽然……但是…… (HSK 3)."},{"context":"“Đi xe đạp điện ít nhất cũng nhanh được mười phút.”","pre":"骑电动车至少","blank":"能","post":"快十分钟。","options":["能","敢","够"],"answer":0,"explanation":"至少 + 能 + V + số lượng."},{"context":"“Cũ thì cũ, nhưng ít ra cũng sạch.” (ôn Bài 3)","pre":"这个房子旧是旧，","blank":"不过","post":"至少很干净。","options":["不过","因为","要是"],"answer":0,"explanation":"×是×，不过至少…… — ôn Bài 3 · điểm 1."},{"type":"sort","context":"Sắp xếp: “Mỗi ngày tôi học ít nhất hai tiếng.”","words":["我","每天","至少","学习","两个小时"],"answer":"我每天至少学习两个小时。","explanation":"Chủ ngữ + thời gian + 至少 + V + thời lượng."},{"type":"sort","context":"Sắp xếp: “Năm nhất cao học phải chọn ít nhất ba môn.”","words":["研究生一年级","至少","要","选","三门课"],"answer":"研究生一年级至少要选三门课。","explanation":"至少 + 要 + V + số lượng."},{"type":"sort","context":"Sắp xếp: “Căn nhà này cũ thì cũ, nhưng ít ra cũng sạch.”","words":["这个","房子","旧是旧","，","不过","至少","很干净"],"answer":"这个房子旧是旧，不过至少很干净。","explanation":"Ôn ×是×，不过…… + 至少."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"我每天睡觉八个小时至少。","isCorrect":false,"correctVersion":"我每天至少睡八个小时。","explanation":"至少 không đứng cuối câu."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"每年至少有两百名留学生来我校学习。","isCorrect":true,"correctVersion":"","explanation":"Đúng: 至少 + 有 + số lượng."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"他至少的朋友有十个。","isCorrect":false,"correctVersion":"他至少有十个朋友。","explanation":"至少 là phó từ, không thêm 的 làm định ngữ."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Muốn học giỏi tiếng Trung, mỗi ngày ít nhất phải học một tiếng.","answer":"要想学好中文，每天至少要学习一个小时。","answerPy":"Yào xiǎng xué hǎo Zhōngwén, měi tiān zhìshǎo yào xuéxí yí gè xiǎoshí.","explanation":"至少 + 要 + V + thời lượng."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Tôi đã đến Bắc Kinh ít nhất năm lần rồi.","answer":"我至少来过北京五次了。","answerPy":"Wǒ zhìshǎo lái guò Běijīng wǔ cì le.","explanation":"至少 + V过 + số lần."}]},{"point":"副词/动词“够” — thật là …; đủ","items":[{"context":"“Trình độ tiếng Trung của cậu cao thật đấy!”","pre":"你的中文水平","blank":"够","post":"高的，这都听懂了！","options":["够","不够","至少"],"answer":0,"explanation":"够 + Adj + 的 = thật là …"},{"context":"“Vẫn chưa đủ ngọt, thêm chút đường đi.”","pre":"我尝了一下，还","blank":"不够","post":"甜，再加一点儿糖吧。","options":["不够","够","至少"],"answer":0,"explanation":"不够 + Adj = chưa đủ …"},{"context":"“Bốn món có đủ không?”","pre":"明天请家月和李文来家里吃饭，四个菜","blank":"够不够","post":"？","options":["够不够","够没够","不够够"],"answer":0,"explanation":"Câu hỏi chính phản: 够不够."},{"context":"“Hôm nay trời lạnh thật đấy, mặc thêm áo vào.”","pre":"今天的天气够冷","blank":"的","post":"，多穿点儿衣服吧。","options":["的","了","吗"],"answer":0,"explanation":"Khung cố định 够……的."},{"context":"“… thời gian không đủ.”","pre":"完成这个工作需要三天，现在只有两天，时间","blank":"不够","post":"。","options":["不够","够的","至少"],"answer":0,"explanation":"N + 不够 (động từ)."},{"type":"sort","context":"Sắp xếp: “Nhà bạn to thật đấy.”","words":["你家","房子","够","大","的"],"answer":"你家房子够大的。","explanation":"够 + Adj + 的."},{"type":"sort","context":"Sắp xếp: “Cái thùng này không đủ to, không để vừa nhiều đồ thế.”","words":["这个","箱子","不够大","，","放不下","这么多东西"],"answer":"这个箱子不够大，放不下这么多东西。","explanation":"不够 + Adj + bổ ngữ khả năng 放不下."},{"type":"sort","context":"Sắp xếp: “Tôi nếm thử rồi, vẫn chưa đủ ngọt.”","words":["我","尝了一下","，","还","不够","甜"],"answer":"我尝了一下，还不够甜。","explanation":"还 + 不够 + Adj."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"这个箱子够不大，放不下这么多东西。","isCorrect":false,"correctVersion":"这个箱子不够大，放不下这么多东西。","explanation":"Phủ định: 不够 + Adj."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"你的中文水平够高的，这都听懂了！","isCorrect":true,"correctVersion":"","explanation":"Đúng: 够……的 cảm thán."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"我们只有两个人，三个菜够了。","isCorrect":true,"correctVersion":"","explanation":"Đúng: 够 làm động từ — đủ (số lượng)."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Món này vẫn chưa đủ cay, cho thêm chút ớt nữa đi.","answer":"这道菜还不够辣，再放一点儿辣椒吧。","answerPy":"Zhè dào cài hái búgòu là, zài fàng yìdiǎnr làjiāo ba.","explanation":"不够 + Adj; từ mới 辣椒."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Hôm nay trời nóng thật đấy!","answer":"今天天气够热的！","answerPy":"Jīntiān tiānqì gòu rè de!","explanation":"够 + Adj + 的."}]},{"point":"固定格式“各×各的” — ai … nấy, mỗi người tự …","items":[{"context":"“… vẫn là ai trả phần nấy thì hợp hơn.”","pre":"大家觉得还是各付","blank":"各","post":"的更合适。","options":["各","自己","每"],"answer":0,"explanation":"各 + V + 各 + 的."},{"context":"“… ai bận việc nấy.”","pre":"到了办公室，大家就开始各","blank":"忙","post":"各的了。","options":["忙","付","坐"],"answer":0,"explanation":"各忙各的."},{"context":"“… ai đọc sách nấy.”","pre":"在图书馆里，大家都很安静，各看各的","blank":"书","post":"。","options":["书","饭","菜"],"answer":0,"explanation":"各V各的 + danh từ."},{"context":"“Khẩu vị họ khác nhau, thế là mỗi người ăn phần mình.” (ôn Bài 3)","pre":"他们口味不同，","blank":"于是","post":"就各吃各的。","options":["于是","甚至","不仅"],"answer":0,"explanation":"于是 nối kết quả — Bài 3 · điểm 4."},{"context":"“… mỗi người mua một kiểu.”","pre":"他们想买的东西不一样，到了商场以后就各买","blank":"各的","post":"了。","options":["各的","自己","他的"],"answer":0,"explanation":"各买各的."},{"type":"sort","context":"Sắp xếp: “Mọi người thấy vẫn là ai trả phần nấy thì hợp hơn.”","words":["大家","觉得","还是","各付各的","更合适"],"answer":"大家觉得还是各付各的更合适。","explanation":"还是……更合适 + 各付各的."},{"type":"sort","context":"Sắp xếp: “Đến văn phòng, mọi người bắt đầu ai bận việc nấy.”","words":["到了","办公室","，","大家","就","开始","各忙各的了"],"answer":"到了办公室，大家就开始各忙各的了。","explanation":"Chủ ngữ số nhiều + 就 + 各V各的."},{"type":"sort","context":"Sắp xếp: “Thầy nói xong, mọi người ai làm bài nấy.”","words":["老师","说完","以后","，","大家","就","各做各的"],"answer":"老师说完以后，大家就各做各的。","explanation":"……以后，大家就各V各的."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"我各吃各的。","isCorrect":false,"correctVersion":"我们各吃各的。","explanation":"Chủ ngữ phải là nhiều người."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"在图书馆里，大家都很安静，各看各的书。","isCorrect":true,"correctVersion":"","explanation":"Đúng: 各看各的 + 书."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"他们各的做各的。","isCorrect":false,"correctVersion":"他们各做各的。","explanation":"Không có 的 sau 各 thứ nhất."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Bạn bè đi ăn với nhau, chúng tôi thường ai trả phần nấy.","answer":"朋友一起吃饭，我们一般各付各的。","answerPy":"Péngyou yìqǐ chīfàn, wǒmen yìbān gè fù gè de.","explanation":"各付各的 + từ mới 聚餐."}]},{"point":"介词“等” — đợi đến khi, chờ đến lúc","items":[{"context":"“… người trẻ phải đợi người già ngồi xuống rồi mới ngồi.”","pre":"如果聚餐时有老人，年轻人要","blank":"等","post":"老人坐下后再坐。","options":["等","在","从"],"answer":0,"explanation":"等 + sự việc + 后，再 + V."},{"context":"“Đợi tớ làm xong bài rồi mới đi chơi với cậu.”","pre":"等我写完作业，","blank":"再","post":"跟你出去玩。","options":["再","又","还"],"answer":0,"explanation":"等……，再…… (việc chưa xảy ra)."},{"context":"“… tàu đã chạy mất rồi.”","pre":"等我们到火车站的时候，火车","blank":"已经","post":"开走了。","options":["已经","正在","马上"],"answer":0,"explanation":"等……的时候，已经……了."},{"context":"“Đừng vội, đợi tớ xong việc thì sẽ đi tìm cậu.”","pre":"别着急，等我忙完了","blank":"就","post":"去找你。","options":["就","才","也"],"answer":0,"explanation":"等……，就…… (đáp án gợi ý của sách)."},{"context":"“Đến lúc chúng tôi chạy tới thì đã không kịp rồi.” (ôn Bài 4)","pre":"","blank":"等","post":"我们赶到的时候，已经来不及了。","options":["等","随着","要是"],"answer":0,"explanation":"等……的时候 + 来不及 (Bài 4 · điểm 4)."},{"type":"sort","context":"Sắp xếp: “Đợi tớ làm xong bài tập rồi đi chơi với cậu.”","words":["等","我","写完作业","，","再","跟你","出去玩"],"answer":"等我写完作业，再跟你出去玩。","explanation":"等……，再……"},{"type":"sort","context":"Sắp xếp: “Người trẻ phải đợi người già ngồi xuống rồi mới ngồi.”","words":["年轻人","要","等","老人","坐下后","再坐"],"answer":"年轻人要等老人坐下后再坐。","explanation":"Chủ ngữ + 要 + 等 + sự việc + 后 + 再 + V."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"我写完作业等，再跟你出去玩。","isCorrect":false,"correctVersion":"等我写完作业，再跟你出去玩。","explanation":"等 đứng đầu vế câu."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"等我们到火车站的时候，火车已经开走了。","isCorrect":true,"correctVersion":"","explanation":"Đúng: 等……的时候，已经……了."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"等你办了信用卡以后，你又能先花钱再还钱了。","isCorrect":false,"correctVersion":"等你办了信用卡以后，你就能先花钱再还钱了。","explanation":"Kết quả khi điều kiện đạt được dùng 就, không dùng 又."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Đợi mọi người đến đủ rồi chúng ta mới bắt đầu ăn.","answer":"等大家都到了，我们再开始吃。","answerPy":"Děng dàjiā dōu dào le, wǒmen zài kāishǐ chī.","explanation":"等……，再……"},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Đợi tôi tốt nghiệp xong, tôi sẽ về nước làm giáo viên.","answer":"等我毕业以后，就回国当老师。","answerPy":"Děng wǒ bìyè yǐhòu, jiù huíguó dāng lǎoshī.","explanation":"等……，就…… + 当 (Bài 1)."}]}],"/lessons/hsk4v3-bai-6.html":[{"point":"形容词“厉害” — … dữ dội, … kinh khủng","items":[{"context":"“… ho dữ lắm.”","pre":"我还发烧，一直咳嗽，咳得很","blank":"厉害","post":"。","options":["厉害","有效","按时"],"answer":0,"explanation":"V + 得 + 很 + 厉害."},{"context":"“… hôm nay chân đau dữ dội.”","pre":"我昨天跑步跑多了，今天腿疼","blank":"得","post":"厉害。","options":["得","的","地"],"answer":0,"explanation":"Bổ ngữ mức độ nối bằng 得."},{"context":"“Món này cay kinh khủng …”","pre":"这道菜辣得","blank":"厉害","post":"，我吃了一口就不敢再吃了。","options":["厉害","好吃","一点儿"],"answer":0,"explanation":"Adj + 得 + 厉害."},{"context":"“Gió thổi mạnh lắm, đợi lát nữa hãy đi.”","pre":"外面风刮","blank":"得","post":"很厉害，咱们等会儿再走吧。","options":["得","了","着"],"answer":0,"explanation":"刮 + 得 + 很厉害."},{"context":"“… mau đi bệnh viện khám đi.” (ôn từ mới)","pre":"我看你病得很厉害，","blank":"赶快","post":"去医院看看吧。","options":["赶快","偶尔","按时"],"answer":0,"explanation":"赶快 + V: giục làm ngay."},{"type":"sort","context":"Sắp xếp: “Bụng tôi đau dữ dội.”","words":["我","肚子","疼","得","很厉害"],"answer":"我肚子疼得很厉害。","explanation":"Adj + 得 + 很厉害."},{"type":"sort","context":"Sắp xếp: “Anh ấy ho rất dữ.”","words":["他","咳嗽","咳","得","特别厉害"],"answer":"他咳嗽咳得特别厉害。","explanation":"Động từ có tân ngữ → lặp động từ."},{"type":"sort","context":"Sắp xếp: “Hôm nay lạnh kinh khủng, mặc thêm áo vào.”","words":["今天","冷","得","厉害","，","多穿点儿衣服"],"answer":"今天冷得厉害，多穿点儿衣服。","explanation":"Adj + 得 + 厉害."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"这道菜辣得很厉害，我不敢吃。","isCorrect":true,"correctVersion":"","explanation":"Đúng: Adj + 得 + 很厉害."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"我很疼得厉害。","isCorrect":false,"correctVersion":"我疼得很厉害。","explanation":"很 đứng trước 厉害, không đứng trước 疼."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"他咳嗽得厉害很。","isCorrect":false,"correctVersion":"他咳嗽得很厉害。","explanation":"Phó từ 很 đứng trước 厉害."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Hôm qua tôi ngủ muộn quá, hôm nay đầu đau dữ dội.","answer":"昨天我睡得太晚了，今天头疼得厉害。","answerPy":"Zuótiān wǒ shuì de tài wǎn le, jīntiān tóu téng de lìhai.","explanation":"头 + 疼 + 得 + (很) + 厉害."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Món này cay kinh khủng, có điều tôi vẫn ăn được.","answer":"这道菜辣得厉害，不过我吃得了。","answerPy":"Zhè dào cài là de lìhai, búguò wǒ chī de liǎo.","explanation":"辣得厉害 + ôn 不过 (Bài 2) và V得了 (Bài 4)."}]},{"point":"固定格式“（没）有什么（好）×的” — có gì mà phải …, chẳng có gì (đáng) …","items":[{"context":"“Cậu với tớ có gì mà phải khách sáo.”","pre":"你跟我有什么好","blank":"客气","post":"的。","options":["客气","厉害","严重"],"answer":0,"explanation":"有什么好 + V + 的."},{"context":"“… chẳng có gì lạ cả.”","pre":"这种事在网上有很多，没有什么奇怪","blank":"的","post":"。","options":["的","了","吗"],"answer":0,"explanation":"Cuối câu bắt buộc có 的."},{"context":"“… chẳng có gì đáng mua.”","pre":"这家商场里的东西都很一般，没有什么","blank":"好","post":"买的。","options":["好","很","太"],"answer":0,"explanation":"好 + V = đáng để làm."},{"context":"“Tớ chỉ bị cảm nhẹ, chẳng có gì phải lo.”","pre":"我得的只是小感冒，没有什么好","blank":"担心","post":"的。","options":["担心","放心","高兴"],"answer":0,"explanation":"没有什么好担心的."},{"context":"“… chẳng có gì phải dọn.”","pre":"前天刚打扫过，还很干净，","blank":"没有","post":"什么好打扫的。","options":["没有","不是","不"],"answer":0,"explanation":"Phủ định dùng 没有什么, không dùng 不什么."},{"type":"sort","context":"Sắp xếp: “Chúng mình là bạn thân, chẳng có gì phải khách sáo.”","words":["咱们","是","好朋友","，","没有什么","好","客气","的"],"answer":"咱们是好朋友，没有什么好客气的。","explanation":"没有什么 + 好 + V + 的."},{"type":"sort","context":"Sắp xếp: “Vấn đề này đơn giản lắm, có gì mà phải bàn.”","words":["这个问题","很简单","，","有什么","好","讨论","的"],"answer":"这个问题很简单，有什么好讨论的？","explanation":"有什么好 + V + 的: hỏi tu từ."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"你跟我有什么好客气的。","isCorrect":true,"correctVersion":"","explanation":"Đúng: câu hỏi tu từ, gạt đi lời cảm ơn."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"这部电影很一般，没有什么好看。","isCorrect":false,"correctVersion":"这部电影很一般，没有什么好看的。","explanation":"Thiếu 的 cuối câu."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"考试很简单，没有什么好紧张的。","isCorrect":true,"correctVersion":"","explanation":"Đúng: 没有什么好 + V + 的."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Chúng ta là bạn bè, có gì mà phải khách sáo.","answer":"我们是朋友，有什么好客气的。","answerPy":"Wǒmen shì péngyou, yǒu shénme hǎo kèqi de.","explanation":"有什么好客气的."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Bộ phim này rất bình thường, chẳng có gì đáng xem.","answer":"这部电影很一般，没有什么好看的。","answerPy":"Zhè bù diànyǐng hěn yìbān, méiyǒu shénme hǎokàn de.","explanation":"没有什么好看的."}]},{"point":"频率副词“偶尔” — thỉnh thoảng, lâu lâu mới","items":[{"context":"“… lâu lâu mới ốm một lần.”","pre":"她平时身体不错，","blank":"偶尔","post":"才会生一次病。","options":["偶尔","经常","总是"],"answer":0,"explanation":"偶尔 + 才: hiếm khi."},{"context":"“… thỉnh thoảng mới ra rạp.”","pre":"他经常在家看电影，偶尔","blank":"才","post":"去电影院看。","options":["才","就","都"],"answer":0,"explanation":"偶尔才 + V."},{"context":"“… thỉnh thoảng đi ăn ngoài với bạn.”","pre":"我一般都在学校食堂吃饭，","blank":"偶尔","post":"会跟朋友一起出去吃。","options":["偶尔","一直","按时"],"answer":0,"explanation":"一般……，偶尔……"},{"context":"“… có điều thỉnh thoảng cũng muốn ăn đồ ngọt.”","pre":"我喜欢吃辣的菜，不过偶尔","blank":"也","post":"想吃点儿甜的。","options":["也","才","就"],"answer":0,"explanation":"偶尔也 = cũng có lúc."},{"context":"“… uống thuốc đúng giờ.” (phân biệt với 偶尔)","pre":"医生让她回家以后","blank":"按时","post":"吃药，多喝水，多休息。","options":["按时","偶尔","光"],"answer":0,"explanation":"Uống thuốc phải 按时, không thể 偶尔."},{"type":"sort","context":"Sắp xếp: “Tôi thường đi tàu điện ngầm, thỉnh thoảng mới đi taxi.”","words":["我","一般","坐地铁","，","偶尔","才","打车"],"answer":"我一般坐地铁，偶尔才打车。","explanation":"一般……，偶尔才……"},{"type":"sort","context":"Sắp xếp: “Bình thường anh ấy không uống rượu, thỉnh thoảng uống một chút.”","words":["他","平时","不喝酒","，","偶尔","会","喝一点儿"],"answer":"他平时不喝酒，偶尔会喝一点儿。","explanation":"偶尔会 + V."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"我吃偶尔辣的菜。","isCorrect":false,"correctVersion":"我偶尔吃辣的菜。","explanation":"偶尔 đứng trước động từ."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"她身体很好，偶尔才生一次病。","isCorrect":true,"correctVersion":"","explanation":"Đúng: 偶尔才 + 生一次病."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"他每天都偶尔去跑步。","isCorrect":false,"correctVersion":"他偶尔去跑步。","explanation":"每天都 (ngày nào cũng) mâu thuẫn với 偶尔."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Tôi thường học ở thư viện, thỉnh thoảng mới học ở ký túc xá.","answer":"我经常在图书馆学习，偶尔才在宿舍学习。","answerPy":"Wǒ jīngcháng zài túshūguǎn xuéxí, ǒu'ěr cái zài sù shè xuéxí.","explanation":"经常 / 一般……，偶尔才……"},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Anh ấy rất ít khi ốm, thỉnh thoảng mới bị cảm một lần.","answer":"他很少生病，偶尔才感冒一次。","answerPy":"Tā hěn shǎo shēngbìng, ǒu'ěr cái gǎnmào yí cì.","explanation":"偶尔才 + V + 一次."}]},{"point":"目的复句“……，好……” — …, để (tiện / dễ) …","items":[{"context":"“… để đưa ra cách điều trị phù hợp.”","pre":"医生有时还会做一些检查，","blank":"好","post":"给出合适的治疗方法。","options":["好","就","才"],"answer":0,"explanation":"……，好 + V (mục đích)."},{"context":"“Các bạn tìm hiểu tình hình trước …”","pre":"你们先了解一下","blank":"情况","post":"，好做出决定。","options":["情况","过程","结果"],"answer":0,"explanation":"了解 + 情况."},{"context":"“… sau này có việc gì thì tiện liên lạc với tôi.”","pre":"我把电话号码告诉你，以后有什么事","blank":"好","post":"联系我。","options":["好","再","又"],"answer":0,"explanation":"好 đứng ngay trước động từ 联系."},{"context":"“… để họ yên tâm.”","pre":"我每天都给家人打电话，好","blank":"让","post":"他们放心。","options":["让","被","把"],"answer":0,"explanation":"好 + 让 + ai + Adj."},{"context":"“Khám bệnh ở Trung Quốc phải lấy số trước …” (ôn từ mới)","pre":"在中国看病要先","blank":"挂号","post":"，然后再去找医生。","options":["挂号","打针","收费"],"answer":0,"explanation":"先挂号，然后再看病."},{"type":"sort","context":"Sắp xếp: “Bạn ngủ sớm đi, để mai còn dậy sớm.”","words":["你","早点儿","睡","，","明天","好","早起"],"answer":"你早点儿睡，明天好早起。","explanation":"Trạng ngữ 明天 + 好 + V."},{"type":"sort","context":"Sắp xếp: “Xin để lại địa chỉ, để chúng tôi tiện gửi đồ cho bạn.”","words":["请","留下","你的地址","，","我们","好","给你寄东西"],"answer":"请留下你的地址，我们好给你寄东西。","explanation":"Chủ ngữ 我们 + 好 + V."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"我把电话号码告诉你，以后有什么事好联系我。","isCorrect":true,"correctVersion":"","explanation":"Đúng: 好 đứng trước 联系."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"好让他们放心，我每天给家人打电话。","isCorrect":false,"correctVersion":"我每天给家人打电话，好让他们放心。","explanation":"Vế 好 (mục đích) đặt sau."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"你先在大厅休息，我去排队挂号，好节省时间。","isCorrect":true,"correctVersion":"","explanation":"Đúng: vế cuối 好 + V nêu mục đích."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Bạn mang theo hộ chiếu, để tiện đi lấy số.","answer":"你带上护照，好去挂号。","answerPy":"Nǐ dài shàng hùzhào, hǎo qù guàhào.","explanation":"……，好 + V."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Tôi ghi lại các bước nấu món ăn, để lần sau dễ làm.","answer":"我把做菜的过程写下来，下次好做。","answerPy":"Wǒ bǎ zuò cài de guòchéng xiě xiàlái, xià cì hǎo zuò.","explanation":"Trạng ngữ 下次 + 好 + V."}]}],"/lessons/hsk4v3-bai-7.html":[{"point":"固定格式“在……方面” — về mặt …, trong lĩnh vực …","items":[{"context":"“Về mặt nội dung, chị thấy có chỗ nào cần sửa không?”","pre":"","blank":"在","post":"内容方面，您觉得有需要改的吗？","options":["在","从","对"],"answer":0,"explanation":"Cấu trúc cố định: 在 + N + 方面."},{"context":"“Về mặt sắp xếp thời gian …”","pre":"在时间安排","blank":"方面","post":"，你可以再想一想。","options":["方面","一方面","地方"],"answer":0,"explanation":"在……方面 khoanh vùng một mặt; 一方面 dùng khi liệt kê hai mặt (Bài 1)."},{"context":"“… về mặt sinh hoạt vẫn chưa quen lắm.”","pre":"他才来中国两个月，在生活方面，还不太","blank":"习惯","post":"。","options":["习惯","经验","产品"],"answer":0,"explanation":"不太习惯 = chưa quen lắm."},{"context":"“Về mặt giá cả, mua trên mạng thường rẻ hơn cửa hàng.” (ôn 往往 – Bài 4)","pre":"在价格方面，网购","blank":"往往","post":"比商店便宜。","options":["往往","及时","提前"],"answer":0,"explanation":"往往 = thường thường (theo quy luật)."},{"context":"“Con trai tôi về mặt học tập thể hiện rất tốt.” (ôn 表现 – Bài 1)","pre":"我儿子在学习方面","blank":"表现","post":"很好。","options":["表现","效果","内容"],"answer":0,"explanation":"表现很好 = biểu hiện / thể hiện tốt."},{"type":"sort","context":"Sắp xếp: “Về mặt nội dung, chị thấy có chỗ nào cần sửa không?”","words":["在","内容","方面","，","您","觉得","有需要改的吗"],"answer":"在内容方面，您觉得有需要改的吗？","explanation":"在 + N + 方面 đứng đầu câu."},{"type":"sort","context":"Sắp xếp: “Về mặt công việc, cô ấy vừa cẩn thận vừa nghiêm túc.”","words":["她","在","工作","方面","既","细心","又","认真"],"answer":"她在工作方面既细心又认真。","explanation":"Chủ ngữ + 在……方面 + vị ngữ; ôn 既……又…… (Bài 4)."},{"type":"sort","context":"Sắp xếp: “Về mặt sinh hoạt, anh ấy vẫn chưa quen lắm.”","words":["在","生活","方面","，","他","还","不太习惯"],"answer":"在生活方面，他还不太习惯。","explanation":"在……方面 đứng đầu câu hoặc sau chủ ngữ."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"他在交流方面能力很强。","isCorrect":true,"correctVersion":"","explanation":"Đúng: 在交流方面 đứng trước vị ngữ."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"她很细心在工作方面。","isCorrect":false,"correctVersion":"她在工作方面很细心。","explanation":"在……方面 phải đứng TRƯỚC vị ngữ 很细心."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"在学习方面上，他的表现很好。","isCorrect":false,"correctVersion":"在学习方面，他的表现很好。","explanation":"Không thêm 上 sau 方面."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Về mặt nội dung, bản kế hoạch này chẳng có gì phải sửa.","answer":"在内容方面，这个计划书没有什么好改的。","answerPy":"Zài nèiróng fāngmiàn, zhège jìhuà shū méiyǒu shénme hǎo gǎi de.","explanation":"在……方面 + 没有什么好×的 (Bài 6 · điểm 2)."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Về mặt giá cả, mua trên mạng thường rẻ hơn ở cửa hàng.","answer":"在价格方面，网购往往比商店便宜。","answerPy":"Zài jiàgé fāngmiàn, wǎng gòu wǎngwǎng bǐ shāngdiàn piányi.","explanation":"在价格方面 + 往往 (Bài 4) + câu so sánh 比."}]},{"point":"因果复句“既然……，就……” — đã … thì …","items":[{"context":"“Đã đi công tác không lâu thì …”","pre":"","blank":"既然","post":"出差时间不长，就要安排好时间。","options":["既然","虽然","不但"],"answer":0,"explanation":"既然……，就……: tiền đề → kết luận."},{"context":"“… thì chúng ta làm như vậy đi.”","pre":"既然大家都同意，我们","blank":"就","post":"这么做吧。","options":["就","才","都"],"answer":0,"explanation":"就 đứng sau chủ ngữ 我们."},{"context":"“… thì đừng sửa nữa.”","pre":"既然你们已经决定了，就不要再","blank":"改","post":"了。","options":["改","谈","管理"],"answer":0,"explanation":"不要再改了 = đừng sửa nữa."},{"context":"“Bạn đã có kinh nghiệm về mặt này thì giới thiệu cho chúng tôi đi.”","pre":"既然你有这方面的","blank":"经验","post":"，就给我们介绍一下吧。","options":["经验","产品","市场"],"answer":0,"explanation":"有……方面的经验."},{"context":"“Đã không kịp nữa thì đi taxi thôi.” (ôn Bài 4)","pre":"既然","blank":"来不及","post":"了，我们就坐出租车去吧。","options":["来不及","来得及","来不了"],"answer":0,"explanation":"来不及 = không kịp (thời gian)."},{"type":"sort","context":"Sắp xếp: “Mọi người đã đồng ý cả thì chúng ta làm như vậy đi.”","words":["既然","大家","都同意","，","我们","就","这么做吧"],"answer":"既然大家都同意，我们就这么做吧。","explanation":"既然……，Sub + 就……"},{"type":"sort","context":"Sắp xếp: “Bạn đã không khỏe thì về nhà nghỉ đi.”","words":["既然","你","不舒服","，","就","回家","休息吧"],"answer":"既然你不舒服，就回家休息吧。","explanation":"既然 có thể đứng trước hoặc sau chủ ngữ."},{"type":"sort","context":"Sắp xếp: “Đã đi công tác không lâu thì phải sắp xếp thời gian cho tốt.”","words":["既然","出差时间","不长","，","就要","安排好","时间"],"answer":"既然出差时间不长，就要安排好时间。","explanation":"Câu trong bài khoá 2."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"既然你已经决定了，我也不说什么了。","isCorrect":true,"correctVersion":"","explanation":"Đúng: vế sau có thể dùng 也."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"既然他生病了，所以没来上课。","isCorrect":false,"correctVersion":"因为他生病了，所以没来上课。","explanation":"Kể nguyên nhân – kết quả khách quan dùng 因为……所以……; vế sau của 既然 là kết luận / đề nghị."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"既然下雨了，就咱们不出去了吧。","isCorrect":false,"correctVersion":"既然下雨了，咱们就不出去了吧。","explanation":"就 đứng sau chủ ngữ 咱们."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Đã đến rồi thì ngồi thêm một lúc nữa đi.","answer":"既然来了，就再坐一会儿吧。","answerPy":"Jìrán lái le, jiù zài zuò yíhuìr ba.","explanation":"既然……，就…… + 吧 (lời mời, đề nghị)."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Đã không có cơ hội phát triển thì đổi một công việc khác đi.","answer":"既然没有发展机会，就换一个工作吧。","answerPy":"Jìrán méiyǒu fāzhǎn jīhuì, jiù huàn yí gè gōngzuò ba.","explanation":"Đáp án gợi ý của sách; 一份工作 (lượng từ 份 – từ mới)."}]},{"point":"固定格式“拿……来说” — lấy … mà nói, ví dụ như …","items":[{"context":"“Lấy mua sắm mà nói …”","pre":"现在的生活很方便。","blank":"拿","post":"购物来说，人们不出门就能买到想要的东西。","options":["拿","对","把"],"answer":0,"explanation":"Dẫn ví dụ → 拿……来说."},{"context":"“Lấy chuyện ăn uống mà nói …”","pre":"在中国，南北方的生活习惯不同。拿吃饭来","blank":"说","post":"，一般南方人更爱吃米饭。","options":["说","看","想"],"answer":0,"explanation":"Cấu trúc cố định 拿……来说."},{"context":"“Lấy việc trao đổi với khách hàng mà nói …”","pre":"她也遇到了一些困难。拿和客户","blank":"交流","post":"来说，实际效果并不理想。","options":["交流","产品","效果"],"answer":0,"explanation":"Giữa 拿 và 来说 có thể là cụm động từ: 和客户交流."},{"context":"“Lấy tốc độ mà nói, hôm nay mua mai đã nhận.” (ôn 速度 – Bài 4)","pre":"网购有很多优点。拿","blank":"速度","post":"来说，今天买的东西明天就能收到。","options":["速度","能力","基础"],"answer":0,"explanation":"Ví dụ về ưu điểm “tốc độ” của mua hàng trên mạng."},{"context":"“Lấy môi trường mà nói, đâu cũng có hoa …” (ôn Bài 2)","pre":"这个小区很不错。拿","blank":"环境","post":"来说，到处都是花，还种了很多树。","options":["环境","房租","经验"],"answer":0,"explanation":"Hoa, cây → nói về 环境."},{"type":"sort","context":"Sắp xếp: “Lấy chuyện ăn uống mà nói, người miền Nam thường thích ăn cơm hơn.”","words":["拿","吃饭","来说","，","一般","南方人","更爱吃","米饭"],"answer":"拿吃饭来说，一般南方人更爱吃米饭。","explanation":"拿 + N + 来说，……"},{"type":"sort","context":"Sắp xếp: “Lấy mua sắm mà nói, người ta không ra khỏi nhà cũng mua được thứ mình muốn.”","words":["拿","购物","来说","，","人们","不出门","就能","买到想要的东西"],"answer":"拿购物来说，人们不出门就能买到想要的东西。","explanation":"Ví dụ của sách."},{"type":"sort","context":"Sắp xếp: “Lấy tôi làm ví dụ, mỗi ngày tôi học ít nhất hai tiếng.”","words":["拿","我","来说","，","我","每天","至少","学习两个小时"],"answer":"拿我来说，我每天至少学习两个小时。","explanation":"拿 + người + 来说; ôn 至少 (Bài 5)."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"这家饭馆的菜很好吃。拿水煮鱼来说，又香又辣。","isCorrect":true,"correctVersion":"","explanation":"Đúng: nhận định chung trước, ví dụ 拿……来说 sau (水煮鱼 – Bài 5)."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"我们班同学经常互相帮助。拿学习说，大家经常一起研究难题。","isCorrect":false,"correctVersion":"我们班同学经常互相帮助。拿学习来说，大家经常一起研究难题。","explanation":"Thiếu 来."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"拿我来说，这个问题太难了。","isCorrect":false,"correctVersion":"对我来说，这个问题太难了。","explanation":"Nói cảm nhận của một người → 对……来说."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Giao thông thành phố này rất thuận tiện. Lấy tàu điện ngầm mà nói, đi đâu cũng tiện.","answer":"这个城市的交通很方便。拿地铁来说，去哪儿都很方便。","answerPy":"Zhègè chéngshì de jiāotōng hěn fāngbiàn. Ná dìtiě láishuō, qù nǎr dōu hěn fāngbiàn.","explanation":"Nhận định chung + 拿……来说 + ví dụ."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Lớp nào cũng có ưu điểm. Lấy lớp chúng tôi mà nói, các bạn thường xuyên giúp đỡ lẫn nhau.","answer":"每个班都有优点。拿我们班来说，同学之间经常互相帮助。","answerPy":"Měi gè bān dōu yǒu yōudiǎn. Ná wǒmen bān láishuō, tóngxué zhī jiān jīngcháng hùxiāng bāngzhù.","explanation":"优点 (từ mới) + ôn 之间, 互相 (Bài 4)."}]},{"point":"兼语句“主语+使+宾语+动词短语” — A khiến (làm cho) B …","items":[{"context":"“Phương pháp mới khiến công việc đơn giản hơn.”","pre":"这个新方法","blank":"使","post":"工作变得更加简单了。","options":["使","被","把"],"answer":0,"explanation":"A + 使 + B + 变得 + Adj."},{"context":"“… khiến sự phát triển của bản thân bị ảnh hưởng.”","pre":"如果总是换工作，可能会使自己的发展","blank":"受到","post":"影响。","options":["受到","得到","收到"],"answer":0,"explanation":"受到影响 = bị ảnh hưởng."},{"context":"“… giúp du học sinh nhanh chóng thích nghi với cuộc sống đại học.” (ôn 适应 – Bài 1)","pre":"参加这些交流活动使留学生更快","blank":"适应","post":"了大学生活。","options":["适应","进入","积累"],"answer":0,"explanation":"适应 + 生活 / 环境."},{"context":"“Lâu không nghỉ ngơi có thể khiến sức khỏe bị ảnh hưởng.”","pre":"长时间不休息可能会使","blank":"健康","post":"受到影响。","options":["健康","效果","能力"],"answer":0,"explanation":"Đáp án gợi ý của sách."},{"context":"“… thích nghi với môi trường làm việc mới.”","pre":"和同事多交流可以使你更快适应新的工作","blank":"环境","post":"。","options":["环境","产品","内容"],"answer":0,"explanation":"工作环境 = môi trường làm việc."},{"type":"sort","context":"Sắp xếp: “Phương pháp mới này khiến công việc trở nên đơn giản hơn.”","words":["这个","新方法","使","工作","变得","更加简单了"],"answer":"这个新方法使工作变得更加简单了。","explanation":"Chủ ngữ + 使 + tân ngữ + 变得 + Adj."},{"type":"sort","context":"Sắp xếp: “Lần khảo sát thị trường này giúp chúng tôi hiểu suy nghĩ của khách hàng hơn.”","words":["这次","市场调查","使","我们","更了解","客户的想法"],"answer":"这次市场调查使我们更了解客户的想法。","explanation":"我们 vừa là tân ngữ của 使 vừa là chủ ngữ của 了解."},{"type":"sort","context":"Sắp xếp: “Mua sắm trên mạng khiến cuộc sống của mọi người tiện hơn.”","words":["网购","使","人们的生活","更加","方便了"],"answer":"网购使人们的生活更加方便了。","explanation":"使 + B + 更加 + Adj (ôn Bài 3, 4)."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"这个消息使大家都很高兴。","isCorrect":true,"correctVersion":"","explanation":"Đúng: sự việc (消息) khiến mọi người vui."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"老师使我们写一篇作文。","isCorrect":false,"correctVersion":"老师让我们写一篇作文。","explanation":"Giao việc, sai bảo dùng 让, không dùng 使."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"这次出差使积累了很多经验。","isCorrect":false,"correctVersion":"这次出差使我积累了很多经验。","explanation":"Sau 使 phải có tân ngữ (我)."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Thường xuyên thức khuya sẽ khiến sức khỏe bị ảnh hưởng.","answer":"经常熬夜会使健康受到影响。","answerPy":"Jīngcháng áoyè huì shǐ jiànkāng shòudào yǐngxiǎng.","explanation":"会 + 使 + B + 受到影响."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Chuyến công tác lần này giúp tôi tích lũy được không ít kinh nghiệm.","answer":"这次出差使我积累了不少经验。","answerPy":"Zhè cì chūchāi shǐ wǒ jīlěi le bù shǎo jīngyàn.","explanation":"出差, 积累, 经验 (từ mới) + 使."}]}],"/lessons/hsk4v3-bai-8.html":[{"point":"条件复句“不管……，都/也……” — bất kể …, đều / cũng …","items":[{"context":"“Đi đâu cũng được, miễn là nơi có thể thư giãn.”","pre":"","blank":"不管","post":"去哪儿，能放松的地方都行。","options":["不管","虽然","因为"],"answer":0,"explanation":"不管 + từ để hỏi (哪儿)，都……"},{"context":"“Bất kể có suy nghĩ gì, bạn cũng phải nói ra.”","pre":"不管有什么想法，你","blank":"都","post":"要说出来。","options":["都","就","才"],"answer":0,"explanation":"Vế sau của 不管 dùng 都 / 也."},{"context":"“Bất kể thời tiết tốt hay không …”","pre":"不管天气","blank":"好不好","post":"，他每天都去跑步。","options":["好不好","很好","不好"],"answer":0,"explanation":"Sau 不管 dùng dạng lựa chọn Adj不Adj, không dùng 很好 (sự thật xác định)."},{"context":"“Dù gặp khó khăn lớn đến đâu, chúng ta cũng phải kiên trì.”","pre":"不管遇到多大困难，我们","blank":"也","post":"要坚持。","options":["也","还","再"],"answer":0,"explanation":"都 / 也 đứng sau chủ ngữ 我们."},{"context":"“Dù bận đến đâu …” (ôn 至少 – Bài 5)","pre":"不管","blank":"多","post":"忙，他每个星期都至少锻炼两次。","options":["多","很","太"],"answer":0,"explanation":"不管 + 多 + Adj = dù … đến đâu."},{"type":"sort","context":"Sắp xếp: “Bất kể căn nhà này to hay nhỏ, tôi cũng thuê.”","words":["不管","这个房子","大还是小","，","我","都要租"],"answer":"不管这个房子大还是小，我都要租。","explanation":"不管 + A还是B，Sub + 都……"},{"type":"sort","context":"Sắp xếp: “Bất kể ai đến, bạn cũng phải báo cho tôi.”","words":["不管","谁","来","，","你","都","要告诉我"],"answer":"不管谁来，你都要告诉我。","explanation":"不管 + 谁 (từ để hỏi)."},{"type":"sort","context":"Sắp xếp: “Dù đi du lịch ở đâu, cô ấy cũng đội chiếc mũ này.”","words":["不管","去哪儿","旅游","，","她","都","戴着这顶帽子"],"answer":"不管去哪儿旅游，她都戴着这顶帽子。","explanation":"Từ mới 戴, 帽子 + 不管……都……"},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"不管明天下不下雨，我们都去参观故宫。","isCorrect":true,"correctVersion":"","explanation":"Đúng: 不管 + V不V，Sub + 都……"},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"不管天气很热，他也戴着帽子。","isCorrect":false,"correctVersion":"不管天气多热，他都戴着帽子。","explanation":"Sau 不管 không dùng sự thật xác định 很热 → dùng 多热."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"不管有什么问题，都你可以问我。","isCorrect":false,"correctVersion":"不管有什么问题，你都可以问我。","explanation":"都 đứng sau chủ ngữ 你."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Bất kể đi đâu, chỉ cần thư giãn được là được.","answer":"不管去哪儿，能放松就行。","answerPy":"Bùguǎn qù nǎr, néng fàngsōng jiù xíng.","explanation":"不管 + từ để hỏi，……都 / 就行."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Dù công việc bận đến đâu, cuối tuần anh ấy cũng đi ngoại ô thư giãn.","answer":"不管工作多忙，周末他都去郊区放松。","answerPy":"Bùguǎn gōngzuò duō máng, zhōumò tā dōu qù jiāoqū fàngsōng.","explanation":"不管 + 多 + Adj，Sub + 都 / 也……"}]},{"point":"假设复句“……，否则……” — …, nếu không thì …","items":[{"context":"“… nếu không mất sức khỏe thì chẳng đáng.”","pre":"还是别给自己太大压力，","blank":"否则","post":"，失去健康就不值得了。","options":["否则","因此","不过"],"answer":0,"explanation":"Lời khuyên，否则 + hậu quả."},{"context":"“… nếu không rất dễ hỏng.”","pre":"吃不完的菜要放进冰箱，否则很容易","blank":"坏","post":"。","options":["坏","好","新鲜"],"answer":0,"explanation":"Vế sau của 否则 là hậu quả xấu."},{"context":"“… nếu không sáng mai dậy không nổi.” (ôn bổ ngữ khả năng – Bài 4)","pre":"今晚早点儿睡吧，否则明天早上","blank":"起不来","post":"。","options":["起不来","起得来","起来了"],"answer":0,"explanation":"起不来 = không dậy nổi."},{"context":"“Ra ngoài nhớ đội mũ, nếu không sẽ bị nắng làm đau đầu.”","pre":"外出记得戴帽子，","blank":"否则","post":"会被太阳晒得头疼。","options":["否则","所以","并"],"answer":0,"explanation":"否则 đứng đầu vế sau."},{"context":"“… nếu không sẽ không kịp.” (ôn Bài 4 · điểm 4)","pre":"我们得马上出发，否则就","blank":"来不及","post":"了。","options":["来不及","来得及","不来"],"answer":0,"explanation":"来不及 = không kịp."},{"type":"sort","context":"Sắp xếp: “Đừng thức khuya nữa, nếu không cơ thể sẽ không chịu nổi đâu.”","words":["别","熬夜了","，","否则","身体","会","受不了的"],"answer":"别熬夜了，否则身体会受不了的。","explanation":"Lời khuyên，否则 + hậu quả (ôn V不了 – Bài 4)."},{"type":"sort","context":"Sắp xếp: “Đi nhanh lên, nếu không chúng ta sẽ bị muộn.”","words":["快","走吧","，","否则","我们","就要","迟到了"],"answer":"快走吧，否则我们就要迟到了。","explanation":"否则……就要……了."},{"type":"sort","context":"Sắp xếp: “Mang ô theo, nếu không trời mưa thì phiền lắm.”","words":["带上","雨伞","，","否则","下雨","就","麻烦了"],"answer":"带上雨伞，否则下雨就麻烦了。","explanation":"否则 + điều kiện + 就 + hậu quả."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"你得按时吃饭，否则对身体不好。","isCorrect":true,"correctVersion":"","explanation":"Đúng: yêu cầu，否则 + hậu quả xấu."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"否则会感冒，你多穿点儿衣服。","isCorrect":false,"correctVersion":"你多穿点儿衣服，否则会感冒。","explanation":"否则 đứng ở đầu vế sau."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"多休息吧，否则工作效率会更高。","isCorrect":false,"correctVersion":"多休息吧，否则工作效率会下降。","explanation":"Vế sau 否则 phải là hậu quả xấu khi KHÔNG nghỉ ngơi."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Đừng tăng ca nữa, nếu không sức khỏe sẽ bị ảnh hưởng.","answer":"别再加班了，否则健康会受到影响。","answerPy":"Bié zài jiābān le, fǒuzé jiànkāng huì shòudào yǐngxiǎng.","explanation":"Lời khuyên，否则 + hậu quả."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Bạn phải nhắc tôi nhé, nếu không tôi nhất định sẽ quên.","answer":"你要提醒我，否则我一定会忘的。","answerPy":"Nǐ yào tíxǐng wǒ, fǒuzé wǒ yídìng huì wàng de.","explanation":"提醒 (từ mới) + 否则."}]},{"point":"比较句“跟……相比” — so với …","items":[{"context":"“So với tăng ca liên tục …”","pre":"跟一直加班","blank":"相比","post":"，休息好了再工作，效率更高。","options":["相比","比较","一样"],"answer":0,"explanation":"跟 + A + 相比."},{"context":"“So với học thạc sĩ …”","pre":"","blank":"跟","post":"读研究生相比，我更想直接工作。","options":["跟","比","对"],"answer":0,"explanation":"跟……相比 (khẩu ngữ)."},{"context":"“… thanh toán bằng điện thoại tiện hơn.”","pre":"跟用现金相比，手机支付","blank":"更","post":"方便些。","options":["更","很","非常"],"answer":0,"explanation":"Câu so sánh dùng 更, không dùng 很."},{"context":"“So với năm ngoái …” (văn viết)","pre":"","blank":"与","post":"去年相比，今年来这里游玩的人多了一倍。","options":["与","比","被"],"answer":0,"explanation":"与……相比: trang trọng, văn viết."},{"context":"“… không khí ngoại ô trong lành hơn nhiều.”","pre":"跟市区相比，郊区的空气新鲜","blank":"多了","post":"。","options":["多了","很多","非常"],"answer":0,"explanation":"Adj + 多了 = … hơn nhiều."},{"type":"sort","context":"Sắp xếp: “So với đi máy bay, đi tàu cao tốc thoải mái hơn.”","words":["跟","坐飞机","相比","，","坐高铁","更","舒服"],"answer":"跟坐飞机相比，坐高铁更舒服。","explanation":"跟 + A + 相比，B + 更 + Adj."},{"type":"sort","context":"Sắp xếp: “So với trước đây, hiệu suất làm việc của anh ấy đã tăng nhiều.”","words":["与","以前","相比","，","他的","工作效率","提高了很多"],"answer":"与以前相比，他的工作效率提高了很多。","explanation":"与……相比 (văn viết)."},{"type":"sort","context":"Sắp xếp: “So với ở nhà xem tivi, tôi thích đi ngoại ô chơi hơn.”","words":["跟","在家看电视","相比","，","我","更喜欢","去郊区游玩"],"answer":"跟在家看电视相比，我更喜欢去郊区游玩。","explanation":"Chủ ngữ 我 đứng ở vế sau."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"跟市区相比，郊区安静多了。","isCorrect":true,"correctVersion":"","explanation":"Đúng: Adj + 多了 trong câu so sánh."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"跟去年相比，今年的夏天非常热。","isCorrect":false,"correctVersion":"跟去年相比，今年的夏天更热。","explanation":"Câu so sánh dùng 更, không dùng 非常."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"跟一直学习，休息一下效率更高。","isCorrect":false,"correctVersion":"跟一直学习相比，休息一下效率更高。","explanation":"Thiếu 相比."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"So với đi taxi, đi tàu điện ngầm rẻ hơn nhiều.","answer":"跟打车相比，坐地铁便宜多了。","answerPy":"Gēn dǎchē xiāngbǐ, zuò dìtiě piányi duō le.","explanation":"跟……相比，B + Adj + 多了."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"So với nội thành, ngoại ô có núi có sông, phong cảnh đẹp hơn.","answer":"跟市区相比，郊区有山有水，风景更美。","answerPy":"Gēn shìqū xiāngbǐ, jiāoqū yǒu shān yǒu shuǐ, fēngjǐng gèng měi.","explanation":"跟……相比 + 有A有B (điểm 4)."}]},{"point":"固定短语“有A有B” — có A có B","items":[{"context":"“Ngoại ô có núi có sông …”","pre":"郊区有山有","blank":"水","post":"，还有很多农家乐。","options":["水","人","车"],"answer":0,"explanation":"有山有水 — cặp gần nghĩa, chỉ cảnh đẹp."},{"context":"“… có quả to quả nhỏ …”","pre":"超市里的苹果有大有","blank":"小","post":"，有红有绿。","options":["小","多","好"],"answer":0,"explanation":"有大有小 — cặp trái nghĩa."},{"context":"“… có nam có nữ …”","pre":"公园里到处都是人，有男有","blank":"女","post":"，特别热闹。","options":["女","老","人"],"answer":0,"explanation":"有男有女."},{"context":"“Họ ở cùng nhau nói nói cười cười …”","pre":"他们在一起有说有","blank":"笑","post":"，特别开心。","options":["笑","听","哭"],"answer":0,"explanation":"有说有笑 = vừa nói vừa cười, vui vẻ."},{"context":"“Món ăn có món ngọt có món cay …” (ôn từ Bài 5)","pre":"这家饭馆的菜有","blank":"甜","post":"有辣，大家都能找到喜欢的。","options":["甜","饭","好"],"answer":0,"explanation":"有甜有辣 — hai vị khác nhau."},{"type":"sort","context":"Sắp xếp: “Khu vườn nhỏ có hoa có cỏ, rất đẹp.”","words":["小花园里","有花","有草","，","非常","漂亮"],"answer":"小花园里有花有草，非常漂亮。","explanation":"Nơi chốn + 有A有B."},{"type":"sort","context":"Sắp xếp: “Bạn học lớp tôi có nam có nữ, có lớn có nhỏ.”","words":["我们班的同学","有男","有女","，","有大","有小"],"answer":"我们班的同学有男有女，有大有小。","explanation":"Hai cụm 有A有B nối tiếp."},{"type":"sort","context":"Sắp xếp: “Cuộc sống lúc nào cũng có đắng có ngọt.”","words":["生活","总是","有苦","有甜","的"],"answer":"生活总是有苦有甜的。","explanation":"有苦有甜 — trái nghĩa."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"这个地方有山有水，景色十分美丽。","isCorrect":true,"correctVersion":"","explanation":"Đúng: 有山有水 + từ mới 景色, 十分, 美丽."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"市场里的水果有大和有小。","isCorrect":false,"correctVersion":"市场里的水果有大有小。","explanation":"Không thêm 和."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"大家在一起有说笑，特别热闹。","isCorrect":false,"correctVersion":"大家在一起有说有笑，特别热闹。","explanation":"Thiếu chữ 有 thứ hai."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Ngoại ô có núi có sông, ăn, chơi, ở đều rất tiện.","answer":"郊区有山有水，吃、玩、住都十分方便。","answerPy":"Jiāoqū yǒu shān yǒu shuǐ, chī, wán, zhù dōu shífēn fāngbiàn.","explanation":"有A有B + 十分 (từ mới)."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Trong công viên có người lớn có trẻ con, vô cùng náo nhiệt.","answer":"公园里有大人有孩子，十分热闹。","answerPy":"Gōngyuán lǐ yǒu dàrén yǒu háizi, shífēn rènao.","explanation":"A, B hai âm tiết: 有大人有孩子."}]}],"/lessons/hsk4v3-bai-9.html":[{"point":"紧缩复句“不……也……” — không … cũng (vẫn) …","items":[{"context":"“Em không nói anh cũng hiểu em đang nghĩ gì.”","pre":"我不说你","blank":"也","post":"懂我在想什么。","options":["也","就","还"],"answer":0,"explanation":"不……也……: dù không nói, kết quả vẫn là hiểu."},{"context":"“Cậu ấy không ôn cũng thi được điểm cao.”","pre":"他不","blank":"复习","post":"也能考出好成绩。","options":["复习","错过","祝"],"answer":0,"explanation":"不 + V1 (复习) + 也 + kết quả."},{"context":"“… không hỏi tôi cũng biết.”","pre":"我很清楚他为什么生气，","blank":"不","post":"问我也知道。","options":["不","没","别"],"answer":0,"explanation":"Mẫu cố định dùng 不 ở vế đầu."},{"context":"“Đường này tôi đi nhiều lần rồi, không dùng điện thoại cũng tìm được.”","pre":"这条路我走过很多次了，不用手机","blank":"也","post":"能找到。","options":["也","才","再"],"answer":0,"explanation":"不用……也能…… = không cần … cũng có thể …"},{"context":"“Trưa ăn no quá, tối không ăn cũng không đói.”","pre":"我中午吃得太饱了，晚上不吃饭也不","blank":"饿","post":"。","options":["饿","饱","累"],"answer":0,"explanation":"Vế sau có thể là phủ định: 也不饿."},{"type":"sort","context":"Sắp xếp: “Em không nói anh cũng hiểu.”","words":["我","不说","你","也","懂"],"answer":"我不说你也懂。","explanation":"Sub1 + 不 + V1 + Sub2 + 也 + V2."},{"type":"sort","context":"Sắp xếp: “Cậu ấy không ôn cũng thi được điểm cao.”","words":["他","不","复习","也能","考出","好成绩"],"answer":"他不复习也能考出好成绩。","explanation":"不 + V1 + 也能 + V2."},{"type":"sort","context":"Sắp xếp: “Chuyện này không hỏi tôi cũng biết.”","words":["这件事","不问","我","也","知道"],"answer":"这件事不问我也知道。","explanation":"Chủ ngữ vế sau (我) đứng trước 也."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"你不告诉我，我也知道你在想什么。","isCorrect":true,"correctVersion":"","explanation":"Đúng: 不……也…… (có thể có dấu phẩy khi chủ ngữ hai vế khác nhau)."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"我不说也你懂。","isCorrect":false,"correctVersion":"我不说你也懂。","explanation":"也 phải đứng sau chủ ngữ 你."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"不用地图，但是我也能找到。","isCorrect":false,"correctVersion":"不用地图我也能找到。","explanation":"Câu rút gọn không dùng 但是."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Em không nói anh cũng hiểu em đang nghĩ gì.","answer":"我不说你也懂我在想什么。","answerPy":"Wǒ bù shuō nǐ yě dǒng wǒ zài xiǎng shénme.","explanation":"Sub1 + 不 + V + Sub2 + 也 + V."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Bài này dễ quá, không ôn cũng làm được.","answer":"这个题太简单了，不复习也做得了。","answerPy":"Zhège tí tài jiǎndān le, bú fùxí yě zuò de liǎo.","explanation":"不复习也 + V得了 (ôn Bài 4 · điểm 1)."}]},{"point":"转折复句“尽管……，但是/可是……” — mặc dù …, nhưng …","items":[{"context":"“Họ tuy tính cách khác nhau nhưng …”","pre":"他们","blank":"尽管","post":"性格不同，但是有很多共同爱好。","options":["尽管","由于","不管"],"answer":0,"explanation":"尽管……，但是…… (chuyển ngoặt)."},{"context":"“… nhưng họ vẫn hoàn thành nhiệm vụ.”","pre":"尽管时间紧张、压力很大，","blank":"但是","post":"他们还是完成了任务。","options":["但是","所以","而且"],"answer":0,"explanation":"Vế sau của 尽管 dùng 但是 / 可是."},{"context":"“… nhưng vẫn kiên nhẫn đọc truyện cho con.”","pre":"尽管她已经很累了，可是","blank":"还是","post":"很耐心地给女儿读睡前故事。","options":["还是","才","就"],"answer":0,"explanation":"可是 + 还是: nhấn mạnh “vẫn”."},{"context":"“Mặc dù đã sống ở Trung Quốc năm năm, nhưng vẫn chưa quen ăn cay.” (phân biệt 不管 – Bài 8, 既然 – Bài 7)","pre":"","blank":"尽管","post":"他已经在中国住了五年，但是还是不太习惯吃辣的。","options":["尽管","不管","既然"],"answer":0,"explanation":"Sự thật cụ thể + kết quả trái chiều → 尽管."},{"context":"“Mặc dù công việc bận, nhưng anh ấy rất có trách nhiệm với gia đình …”","pre":"尽管工作很忙，但是他对家庭很","blank":"负责","post":"，从来没忘过孩子的生日。","options":["负责","积极","浪漫"],"answer":0,"explanation":"对……负责 = có trách nhiệm với …"},{"type":"sort","context":"Sắp xếp: “Mặc dù lâu lắm không gặp, nhưng mọi người vẫn thấy rất thân quen.”","words":["尽管","很久没见了","，","但是","大家","还是","感觉很熟悉"],"answer":"尽管很久没见了，但是大家还是感觉很熟悉。","explanation":"尽管……，但是 + Sub + 还是……"},{"type":"sort","context":"Sắp xếp: “Anh ấy tuy công việc rất bận nhưng ngày nào cũng gọi cho bạn gái.”","words":["他","尽管","工作很忙","，","可是","每天","都给女朋友打电话"],"answer":"他尽管工作很忙，可是每天都给女朋友打电话。","explanation":"尽管 đứng trước hoặc sau chủ ngữ đều được."},{"type":"sort","context":"Sắp xếp: “Mặc dù tôi rất thích chiếc máy tính đó, nhưng cuối cùng vẫn không mua.”","words":["尽管","我","很喜欢那台电脑","，","但是","最后","还是没有买"],"answer":"尽管我很喜欢那台电脑，但是最后还是没有买。","explanation":"Đáp án tham khảo của sách (bài tập 3)."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"尽管雨下得很大，但是比赛还是按时开始了。","isCorrect":true,"correctVersion":"","explanation":"Đúng: mưa to (sự thật) — trận đấu vẫn bắt đầu đúng giờ."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"尽管他生病了，所以没来上课。","isCorrect":false,"correctVersion":"由于他生病了，所以没来上课。","explanation":"Quan hệ nhân quả → 由于……，所以…… (Bài 2)."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"尽管你说什么，我都不相信。","isCorrect":false,"correctVersion":"不管你说什么，我都不相信。","explanation":"Điều kiện bất kỳ (什么) → 不管……都…… (Bài 8)."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Mặc dù tính cách họ khác nhau, nhưng họ có rất nhiều sở thích chung.","answer":"尽管他们性格不同，但是有很多共同爱好。","answerPy":"Jǐnguǎn tāmen xìnggé bùtóng, dànshì yǒu hěn duō gòngtóng àihào.","explanation":"尽管……，但是 / 可是…… + từ mới 性格, 共同."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Mặc dù đã học tiếng Trung hai năm, nhưng tôi vẫn xem không hiểu phim Trung Quốc.","answer":"尽管我已经学了两年中文，但是还是看不懂中国电影。","answerPy":"Jǐnguǎn wǒ yǐjīng xué le liǎng nián Zhōngwén, dànshì háishì kàn bù dǒng Zhōngguó diànyǐng.","explanation":"但是 + 还是 + V不懂."}]},{"point":"指示代词“此” — này, đây (văn viết, trang trọng)","items":[{"context":"“Chuyến công tác lần này khiến hai người thân quen.”","pre":"","blank":"此","post":"次出差，让两人熟悉了起来。","options":["此","那","哪"],"answer":0,"explanation":"此次 = 这次 (văn viết)."},{"context":"“… nhất định hoàn thành tốt nhiệm vụ.”","pre":"此人聪明、有能力，一定能顺利完成","blank":"任务","post":"。","options":["任务","印象","日子"],"answer":0,"explanation":"完成任务 = hoàn thành nhiệm vụ."},{"context":"“Tài liệu này rất quan trọng, phải giao tận tay anh ấy.”","pre":"此材料很重要，必须直接","blank":"交","post":"给他。","options":["交","让","叫"],"answer":0,"explanation":"交给 + người = giao cho ai."},{"context":"“… từ đó thành bạn tốt.”","pre":"他们一起出了次差，","blank":"从此","post":"成了好朋友。","options":["从此","从来","当时"],"answer":0,"explanation":"从此 = từ mốc đó về sau."},{"context":"“… tôi chịu trách nhiệm về việc này.” (ôn 任何 – Bài 1)","pre":"关于此次活动，大家有任何问题都可以问我，我对","blank":"此","post":"负责。","options":["此","这儿","那儿"],"answer":0,"explanation":"对此负责 = chịu trách nhiệm về việc này."},{"type":"sort","context":"Sắp xếp: “Chuyến công tác lần này khiến hai người thân quen.”","words":["此次","出差","让","两人","熟悉了起来"],"answer":"此次出差让两人熟悉了起来。","explanation":"此次 + N làm chủ ngữ."},{"type":"sort","context":"Sắp xếp: “Công việc này do bạn phụ trách.”","words":["此项","工作","由","你","负责"],"answer":"此项工作由你负责。","explanation":"此 + lượng từ 项 + N; 由 + người + 负责."},{"type":"sort","context":"Sắp xếp: “Chúng tôi đều rất hài lòng về việc này.”","words":["我们","对此","都","很满意"],"answer":"我们对此都很满意。","explanation":"对此 = 对这件事."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"此人做事积极，工作负责，大家都很喜欢他。","isCorrect":true,"correctVersion":"","explanation":"Đúng: 此人 = 这个人 (trang trọng)."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"你看，此是我新买的手机。","isCorrect":false,"correctVersion":"你看，这是我新买的手机。","explanation":"Khẩu ngữ dùng 这 làm chủ ngữ."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"从此以前，他再也没迟到过。","isCorrect":false,"correctVersion":"从此以后，他再也没迟到过。","explanation":"从此 đi với 以后."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Chuyến công tác lần này khiến hai người trở nên thân quen, từ đó thành bạn tốt.","answer":"此次出差让两人熟悉了起来，从此成了好朋友。","answerPy":"Cǐ cì chūchāi ràng liǎng rén shúxī le qǐlái, cóngcǐ chéng le hǎo péngyou.","explanation":"此次 + 从此 (từ mới)."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Người này vừa thông minh vừa có trách nhiệm, việc này giao cho anh ấy là được.","answer":"此人既聪明又负责，这件事交给他就是了。","answerPy":"Cǐ rén jì cōngming yòu fùzé, zhè jiàn shì jiāo gěi tā jiù shì le.","explanation":"此人 + 既……又…… (Bài 4) + 就是了 (Bài 2)."}]},{"point":"时间副词“从来” — từ trước đến nay (luôn / chưa từng)","items":[{"context":"“Tình yêu, từ trước đến nay luôn là …”","pre":"爱，","blank":"从来","post":"都是相互尊重、理解与支持，不是吗？","options":["从来","从此","当时"],"answer":0,"explanation":"从来都是 = từ trước đến nay luôn là."},{"context":"“Tôi chưa từng thấy loài hoa màu này.”","pre":"我从来没见","blank":"过","post":"这个颜色的花，它叫什么名字啊？","options":["过","了","着"],"answer":0,"explanation":"从来没 + V + 过."},{"context":"“Tôi trước giờ không thích đi du lịch một mình.”","pre":"我从来","blank":"不","post":"喜欢一个人旅游，每次都要和家人或朋友一起去。","options":["不","没","别"],"answer":0,"explanation":"Sở thích, thói quen → 从来不."},{"context":"“… chưa từng đến muộn.”","pre":"他工作很负责，从来","blank":"没","post":"迟到过。","options":["没","不","别"],"answer":0,"explanation":"Có 过 → 从来没 + V + 过."},{"context":"“Anh ấy là người rất thật thà, trước giờ không nói dối.”","pre":"他这个人很","blank":"实在","post":"，从来不说假话。","options":["实在","浪漫","积极"],"answer":0,"explanation":"实在 = thật thà (từ mới bài khoá 3)."},{"type":"sort","context":"Sắp xếp: “Tôi chưa từng đến Vạn Lý Trường Thành.”","words":["我","从来","没","去过","长城"],"answer":"我从来没去过长城。","explanation":"从来没 + V + 过 + O."},{"type":"sort","context":"Sắp xếp: “Anh ấy trước giờ không uống cà phê.”","words":["他","从来","不","喝","咖啡"],"answer":"他从来不喝咖啡。","explanation":"从来不 + V: thói quen."},{"type":"sort","context":"Sắp xếp: “Tình yêu từ trước đến nay luôn là ủng hộ lẫn nhau.”","words":["爱","从来","都是","相互","支持的"],"answer":"爱从来都是相互支持的。","explanation":"Khẳng định: 从来都是……"},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"我从来没吃过这么好吃的巧克力。","isCorrect":true,"correctVersion":"","explanation":"Đúng: 从来没 + V + 过."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"她不从来迟到。","isCorrect":false,"correctVersion":"她从来不迟到。","explanation":"从来 đứng trước 不."},{"type":"judge","context":"Xét câu sau đúng hay sai.","sentence":"上个星期六我从来没去公园。","isCorrect":false,"correctVersion":"上个星期六我没去公园。","explanation":"Một thời điểm cụ thể không dùng 从来."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Tôi chưa từng xem bộ phim này, nghe nói rất hay.","answer":"我从来没看过这个电影，听说很精彩。","answerPy":"Wǒ cónglái méi kàn guò zhège diànyǐng, tīngshuō hěn jīngcǎi.","explanation":"从来没 + V + 过 + từ mới 精彩."},{"type":"translate","context":"Dịch sang tiếng Trung.","promptLang":"vi","prompt":"Anh ấy trước giờ không nói dối, bạn cứ yên tâm là được.","answer":"他从来不说假话，你放心就是了。","answerPy":"Tā cónglái bù shuō jiǎ huà, nǐ fàngxīn jiù shì le.","explanation":"从来不 + 就是了 (ôn Bài 2 · điểm 1)."}]}]});
